var __index = {"config": {"lang": ["en"], "separator": "[\\s\\-]+", "pipeline": ["stopWordFilter"]}, "docs": [{"location": "index.html", "title": "Mujeeb's Online Library", "text": ""}, {"location": "index.html#whats-this-site-all-about", "title": "What\u2019s this site all about?", "text": "<p>This site is created to organize and showcase my work for easy reference. Feel free to explore various sections\u2014you might find something useful or inspiring!</p>"}, {"location": "index.html#what-material-is-available-here", "title": "What material is available here?", "text": "<p>You\u2019ll find info here on things like:</p> <pre><code>Software development\n\nWeb Development\n\nLinux programming\n\nEmbedded systems\n\nRobotics (ROS2, OpenRMF, ...)\n\nImage and video processing\n</code></pre> <p>For more details: about me</p>"}, {"location": "index.html#looking-for-something-specific", "title": "Looking for something specific?", "text": "<p>You can use the search bar to look up keywords like ROS2, 5G, OpenRMF, and others. </p> <p>or</p> <p>Sarch through the Keywords...</p>"}, {"location": "index.html#about-me", "title": "About me", "text": "<p>To learn more about me, visit the About Me page.</p>"}, {"location": "tags.html", "title": "Keywords", "text": ""}, {"location": "tags.html#tag:5g", "title": "5G", "text": "<ul> <li>            N3IWF- A brief introduction          </li> <li>            N3IWF- Seamless handover between 5G and Wifi          </li> </ul>"}, {"location": "tags.html#tag:linux", "title": "Linux", "text": "<ul> <li>            A Network Example          </li> <li>            CLI Quick Reference          </li> <li>            Docker Quick Reference          </li> <li>            Docker-Getting Started          </li> <li>            Hello-Docker          </li> </ul>"}, {"location": "tags.html#tag:n3iwf", "title": "N3IWF", "text": "<ul> <li>            N3IWF- A brief introduction          </li> <li>            N3IWF- Seamless handover between 5G and Wifi          </li> </ul>"}, {"location": "tags.html#tag:docker", "title": "docker", "text": "<ul> <li>            A Multi-Client Example          </li> <li>            A Network Example          </li> <li>            Docker Quick Reference          </li> <li>            Docker-Getting Started          </li> <li>            Hello-Docker          </li> </ul>"}, {"location": "tags.html#tag:go", "title": "go", "text": "<ul> <li>            Go Programming          </li> </ul>"}, {"location": "tags.html#tag:golang", "title": "golang", "text": "<ul> <li>            Go Programming          </li> </ul>"}, {"location": "tags.html#tag:goto", "title": "goto", "text": "<ul> <li>            Is goto statement dead?          </li> </ul>"}, {"location": "tags.html#tag:structured-programming", "title": "structured programming", "text": "<ul> <li>            Is goto statement dead?          </li> </ul>"}, {"location": "tags.html#tag:tcp-client", "title": "tcp client", "text": "<ul> <li>            A Multi-Client Example          </li> </ul>"}, {"location": "tags.html#tag:tcp-server", "title": "tcp server", "text": "<ul> <li>            A Multi-Client Example          </li> </ul>"}, {"location": "whatsnew.html", "title": "What is new!!", "text": "<p>This page features newly uploaded content. Check back regularly for the latest updates!</p>"}, {"location": "about/aboutme.html", "title": "About me", "text": ""}, {"location": "about/aboutme.html#technical", "title": "Technical", "text": "<p>I'm a software developer based in Singapore with experience in:</p> <pre><code>Software development \n    Programming (C/C++, Java, Python, Go)\n    Concurrency, multithreading, asynchronousIO\n    Github, Git actions, CI/CD, containers...\n\nWeb Development\n    Backend development with Python and Go\n    Web abd database connectivity\n    REST APIs, Microservices\n    Networking protocols (WebSockets, MQTT, Client/Server )\n    Multimedia streaming, ffmpeg, WebRTC, RTSP\n\nLinux programming\n    Embedded Linux\n    System programming\n    Bash scripting and automation\n\nEmbedded systems design and development\n    Realtime OS and multitasking\n    Cortex M\n    AVR microcontrollers\n    Trimedia processors\n\nRobotics\n    ROS2\n    OpenRMF and fleet management\n    5G connectivity\n    Turtlebot, Yahboom, AMRs\n\nImage and video processing\n    Biometrics/Fingerprint algorithms\n    Face recognition\n    Object detection\n    Traditional and AI algorithms\n</code></pre> <p>Feel free to explore my work throughout the site.</p>"}, {"location": "about/aboutme.html#other-pages", "title": "Other pages", "text": "<p>LinkedIn</p>"}, {"location": "about/contact.html", "title": "My Contact", "text": "<p>My contact information</p>"}, {"location": "blog/index.html", "title": "My Blogs", "text": "<p>Welcome to my miscellaneous writings section!!</p> <p>Browse through my posts by selecting a category from the navigation bar on the left.</p>"}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html", "title": "N3IWF- Seamless handover between 5G and Wifi", "text": "<p>In this post, I\u2019ll share some insights on some basic considerations in order to  be able to utilize N3IWF for seamless handover between 5G networks and Wifi.</p> <p>If you're looking for a more basic introduction to N3IWF, feel free to check out my earlier post:</p> <p>N3IWF Basics</p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#goal", "title": "Goal", "text": "", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#n3iwf-for-handover-between-5g-and-wifi", "title": "N3IWF for handover between 5G and Wifi", "text": "<ul> <li> <p>A key feature of N3IWF is seamless handover and mobility \u2014 for example, a user moving from an outdoor cellular network into an indoor Wi-Fi environment should experience no service interruption.</p> </li> <li> <p>However, not all N3IWF implementations support this functionality. Some vendor solutions may lack this capability, so it\u2019s important to understand the required features and resources when evaluating or deploying an N3IWF solution.</p> </li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#what-happens-during-the-seamless-handover", "title": "What happens during the seamless handover", "text": "<p>During handover between gNB and Wi-Fi via N3IWF, several things happen behind the scenes to ensure a smooth transition:</p> <ul> <li> <p>IP continuity is maintained by anchoring the IP address at the UPF, so the user doesn't lose connectivity.</p> </li> <li> <p>Security tunnels (IPSec/IKEv2) are re-established when switching to or from Wi-Fi via N3IWF.</p> </li> <li> <p>Session and mobility context is preserved by the AMF and SMF to avoid re-authentication or session resets.</p> </li> <li> <p>User data is rerouted through the new access path (N3 or N3IWF), while QoS policies may be updated if needed.</p> </li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#hardware-and-software", "title": "Hardware and software", "text": "<p>There are specific requirements that must be fulfilled both on the UE side and on the vendor side \u2014 particularly within the 5G Core \u2014 to support seamless handover using N3IWF.</p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#hardware-requirements-minimal", "title": "Hardware requirements (Minimal)", "text": "Device Purpose WiFi Access Point Connect UE (phone or laptop) to the N3IWF via WiFi PC/Server running N3IWF Should support IPSec/IKEv2 and N2/N3 toward the 5G Core PC/server running 5G Core Components: AMF, SMF, UPF, UDM, AUS, NRF (from Open5GCore, Free5GC, or vendor) Real UE (phone, laptop) Needs IPSec client and connect SIM/eSIM credentials (with EAP-AKA or EAP-TLS support)", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#software-requirements", "title": "Software requirements", "text": "Software Component details N3IWF software Must support IPSec/IKEv2 + EAP-AKA or EAP-TSL 5G Core software Need AMF, SMF, UPF, AUSF, UDM (Open5GCore or Free5GC work IPSec/IKEv2 client on UE For Windows: strongSwan, For Android: built-in if using eSIM Configuration scripts To define UE Sim profile, keys, and network slicing info (optional) Traffic generatror ipref, ping, Wireshark for testing data sessions over N3", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#what-is-expected-of-a-vendor", "title": "What is expected of a vendor", "text": "<p>If a private 5G testbed is to deployed, following are some possible questions to ask: (this is not comprehensive list, and is included as a guideline only)</p> <ul> <li>Does your N3IWF implementation support interworking mobility between Wi-Fi and 5G NR (gNB)?</li> <li>Does the AMF and SMF in your core network support IP continuity across  access change (Wifi&lt;-&gt;5G)?     (this means same PDU session survives across change--cruicial for seamless handover)</li> <li>Do you support Mult-Access PDU Sessions (MA-PDU)?</li> <li>Is UE route selection policy (URSP) supported?     (needed if the UE needs to decide when to switch between Wifi and 5G)</li> <li>Do you support IKEv2 + EAP-AKA or EAP-TLS for UE authentication over Wifi?</li> <li>Can your system be integrated with UERANSIM or a real gnB for 5G NR?</li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#summary-of-key-components", "title": "Summary of key components", "text": "Component Required Notes gNB/5G radio No Not needed without handover or NR access N3IWF Yes Needs IPSec + Support for real UEs 5G Core Yes Use Open5GCore, Free5GC, etc. Real UE Yes Must support IPSec + SIM Credentaials WiFI AP Yes Acts as non-3GPP access network", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#appendix-1g-to-5g-technology-names", "title": "Appendix: 1G to 5G technology names", "text": "<p>A side note on mobile communication technology names.</p> Technology Name 1G AMPS, NMT 2G GSM, CDMA 3G UMTS(WCDMA), CDMA2000 4G LTE, LTE-Advanced 5G NR (New Radio)", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/28/n3iwf--seamless-handover-between-5g-and-wifi.html#appendix-abbreviations", "title": "Appendix: Abbreviations:", "text": "<ul> <li>AMF: (Access and Mobility Management Function): Manages connection and mobility for devices in the 5G core network.</li> <li>EAP-TLS (Extensible Authentication Protocol-Transport Layer Security):It\u2019s a secure authentication protocol used in networks.</li> <li>gNB (gNodeB): The 5G base station that connects user devices to the network (like the 4G eNodeB).</li> <li>MA-PDU (MAC Service Data Unit Protocol Data Unit): A data packet at the MAC layer in 5G NR.</li> <li>NR (New Radio): The 5G radio access technology (air interface).</li> <li>PDU (Protocol Data Unit): A generic term for a data packet at any layer of the network protocol stack.</li> <li>SMF (Session Management Function): Controls session establishment, modification, and release in the 5G core.</li> <li>UE (User Equipment): The device used by the end-user (e.g., smartphone, IoT device).</li> <li>UERANSIM: An open-source 5G UE and RAN simulator for research and testing.</li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html", "title": "N3IWF- A brief introduction", "text": "<p>3GPP is a global collaboration of telecommunications standards organizations that develops the technical specifications for mobile networks, including:</p> <pre><code>3G (UMTS)\n4G (LTE)\n5G (5G NR, 5G Core)\nNow working on 6G concepts (as of 2025)\n</code></pre> <p>3GPP has defined many functions and standard for 5G communications. One of them is N3IWF.</p> <p>N3IWF stands for Non-3GPP Interworking Function, it is officially part of the 5G standard.</p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#1-major-components-in-a-5g-and-where-5g-core-lies", "title": "1. Major components in a 5G  and where  5G-Core lies", "text": "<p>A 5G mobile system can be broken in following three major components:</p> <pre><code>1. UE (e.g. A phhone)\n2. gNB: Basestaion with antenna that provides connectivity to UE\n3. 5G Core: A backend system that provides actualy functionality e.g.\nuser-authentication, internet access, communication among users etc.\n</code></pre> <p>An anology:     <pre><code>UE (Your phone) = A car\ngNB (5G tower) = The on-ramp to the highway\n5G Core = The traffic control center that:\n    authenticates: Checks who you are\n    routes your data: Allows you onto the highway, and routes you to the right destination\n    security: keeps your data private and secure\n</code></pre></p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#2-what-are-5g-core-functions", "title": "2. What are 5G-Core functions", "text": "<p>A 5G Core is an important part of 5G infrastructure which: <pre><code>- Handles connections and movement between towers\n- Stores your subscriber info and identity information\n- Actually moves your data (like video, messages) across the network\n- Keeps your data private and secure (encryption)\n</code></pre> It implements major 5G functions and protocols such as AMF, SMF, UPF, N3IWF, etc.</p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#where-does-n3iwf-fit", "title": "Where does N3IWF fit", "text": "<p>N3IWF function of 5G lies AFTER gNB, hence it is part of 5G-Core components. In order to be able to use it, the 5G-core implementaiton must support N3IWF functionality.</p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#3-connection-without-n3iwf-traditional", "title": "3. Connection without N3IWF (Traditional)", "text": "<p>A user equipement (UE) such as a mobile phone is connected to the core network through a basestation.  This requires antennas and necessary equipment on the UE itself.  </p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#4-connection-through-n3iwf-gateway-bypass-gnb", "title": "4. Connection through N3IWF Gateway (bypass gNB)", "text": "<p>In a N3IWF-based system, a UE device connects to 5G core THROUGH A GATEWAY (called N3IWF) , without involving gNB.</p> <p>In this case, a device such as a laptop is connected to the core mobile network through a gateway, which provides connections and necessary protocol conversion.</p> <p>N3IWF is a gateway between untrusted non-Mobile networks (like public WiFi) and the 5G core.</p> <p></p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#5-goals-and-benefits-of-n3iwf", "title": "5. Goals and benefits of N3IWF", "text": "<p>There are several reasons for using N3IWF gateway.</p> <ul> <li> <p>Enhanced Security: 5G communication is inherently more secure than Wifi (or other Non-3GPP) technologies. This way we can add SECURITY to untrusted networks like WiFi.</p> </li> <li> <p>Low Avialbility of of Mobile Network: Many environments\u2014like homes, offices, factories, rural areas\u2014don\u2019t have great cellular coverage, but Wi-Fi, fixed broadband, or satellite are available.</p> </li> <li> <p>Cost Reduction and Offloading: Cellular spectrum is expensive and limited. Offloading to Wi-Fi saves capacity for users who truly need cellular bandwidth.</p> </li> <li> <p>No Radio Connction Needed:  Some devices \u2014 such as laptops, tablets, or IoT devices \u2014 don\u2019t have cellular radios or SIM modules, so they can\u2019t connect directly to 5G NR (New Radio).</p> </li> <li> <p>Seamless Handover and Mobility: A user walking from outdoors (cellular) into a building (Wi-Fi) should experience no service drop.</p> </li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#6-real-vs-simulated-ue-modes", "title": "6. \"Real\" vs \"Simulated UE\" modes", "text": "<p>In N3IWF, a device can be connected in either of two modes:</p> <ul> <li> <p>Real mode: In real mode, a physical device (phone, tablet, or PC) with proper support acts as the UE, and it connects to the 5G-Core through N3IWF over Wi-Fi.</p> </li> <li> <p>Simulation mode: you don\u2019t need a real phone or device. The software itself pretends to be the UE and tests how it would behave when connecting to a N3IWF gateway. As long as N3IWF gateway is reachable (even without Wifi), we can reach 5G-Core and do experiemnts with 5G-core functions.</p> </li> </ul> Real ModeSimulated UE Mode <p></p> <p></p>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#7-open5gcore-and-n3iwf", "title": "7. Open5GCore and N3IWF", "text": "<p>Open5GCore is a software implementation of the 5G Core network, developed by the Fraunhofer Institute in Germany, which:</p> <p><pre><code>- follows 3GPP standards (the official rules of how 5G works)\n- implements major 5G Core network functions (like AMF, SMF, UPF, etc.)\n- can be used in universities, private networks, or companies testing 5G tech\n- Useful in non-3GPP access testing, such as:\n    Secure enterprise Wi-Fi + 5G integration\n</code></pre> - Open5GCore software includes an N3IWF implementation that supports both simulated UE mode and real UE mode.</p> <ul> <li> <p>Open5GCore does not support seamless handover between Wi-Fi (N3IWF) and 5G gNB as a built-in, production-ready feature. Open5GCore does not support seamless handover from simulated UE (N3IWF over Wi-Fi) to a real gNB.</p> </li> <li> <p>We can test the following connections to Open5GCore separately:</p> <ul> <li>Connect to Open5GCore over Wi-Fi (N3IWF) \u2014 real or simulated UE</li> <li>Connect to Open5GCore over 5G gNB</li> <li>Switch manually between Wi-Fi and 5G (disconnect Wi-Fi, then connect to 5G) \u2014 but the IP address will be reset, and the session will not be seamless</li> </ul> </li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/07/25/n3iwf--a-brief-introduction.html#8-summary", "title": "8. Summary", "text": "<ul> <li>A 5G network has three major components: UE, gNB, and 5G-Core</li> <li>N3IWF is an alternate method to bypass gNB and connect a UE to 5G-Core using a gateway called N3IWF.</li> <li>The benefits of N3IWF include: Security, availablity of 5G even when signals are not available everywhere (i.e ubiquity), Isolated testing of 5G Core, cost reduction, seamless handover during indoor and outdoors mobility.</li> <li> <p>N3IWF implementations support two modes (either or both)</p> <ul> <li>In simulated UE mode, the UE is virtual and runs inside the computer, using a simulated Wi-Fi environment \u2014 no real Wi-Fi or physical device is involved. This mode is mainly for easy testing and development.</li> <li>In real UE mode, a real device can connect over actual Wi-Fi by establishing an IPSec tunnel to the N3IWF server, enabling real UE registration and session establishment via Wi-Fi. However, this requires additional setup of IPSec/IKEv2/EAP and proper SIM authentication.</li> </ul> </li> <li> <p>Open5GCore is an open-source implementaiton of 5G-Core, that includes N3IWF function as well (alongwith other 5G-Core functions such as AMF, SMF, UPF,...)</p> </li> <li> <p>Open5GCore does not support seamless inter-access handover between Wi-Fi (N3IWF) and 5G gNBaccess as a built-in, production-ready feature. Open5GCore does not support seamless handover from simulated UE (N3IWF over Wi-Fi) to a real gNB.</p> </li> </ul>", "tags": ["5G", "N3IWF"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html", "title": "Is goto statement dead?", "text": "<p>Structured programming became mainstream in the 1970s and 1980s. It  is a programming paradigm that emphasizes writing clear, logical, and well-organized code using:</p> <ol> <li>Sequence \u2013 code runs in order</li> <li>Selection \u2013 decisions using if, else, switch</li> <li>Loops \u2013 repetition using for, while, etc.</li> </ol>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#goto-statment", "title": "goto statment", "text": "<p>A fourth type of statement, the goto statement, was widely used before structured programming. However, it is considered harmful because it makes code harder to understand and maintain.</p> <p>Consider the following two examples\u2014one using a goto statement and one without\u2014to illustrate how goto can impact code readability.</p> code WITH gotocode WITHOUT goto <p><pre><code>#include &lt;stdio.h&gt;\n\nint a = 48, b = 18;  // global for simplicity\nint result;\n\nint main() {\n    goto compute_gcd;\n\nreturn_point:\n    printf(\"GCD is: %d\\n\", result);\n    return 0;\n\n// \"Simulating a function call\"\ncompute_gcd:\n    while (b != 0) {\n        int temp = b;\n        b = a % b;\n        a = temp;\n    }\n    result = a;\n    goto return_point;  // simulate \"return\"\n}\n</code></pre> Note the following about the program (goto version):</p> <ul> <li>It uses two labels: compute_gcd and return_point.</li> <li>The code first jumps to compute_gcd, and after calculating the result, it jumps back to return_point using another goto.</li> <li>If this kind of jumping occurs hundreds of times in a program, it quickly becomes difficult to follow the flow.</li> <li>Moreover, using unclear or unintuitive label names can make the code even harder to understand.</li> <li>In contrast, consider the version of the code that uses functions exclusively \u2014 it\u2019s much clearer and easier to maintain.</li> </ul> <pre><code>#include &lt;stdio.h&gt;\n\nint gcd(int a, int b) {\n    while (b != 0) {\n        int temp = b;\n        b = a % b;\n        a = temp;\n    }\n    return a;\n}\n\nint main() {\n    int result = gcd(48, 18);\n    printf(\"GCD is: %d\\n\", result);\n    return 0;\n}\n</code></pre> <p>Note the following about the program (without goto):</p> <ul> <li> <p>the main() function uses only one statement to perform the task\u2014calling gcd() and then continuing after it returns.</p> </li> <li> <p>instead of using goto jumps, we simply call the function by its name. Although the underlying mechanism involves jumps at the machine level, from the programmer\u2019s perspective it\u2019s just a straightforward statement without explicit jumps or goto.</p> </li> <li> <p>this approach greatly improves the readability and clarity of the code.       </p> </li> </ul>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#goto-statments-replaced-by-functions", "title": "goto statments replaced by functions", "text": "<p>From the examples above, you can see that the same task can be accomplished with a single statement\u2014a function call.</p> <p>From a code reviewer\u2019s perspective, it\u2019s just one statement, even though the function itself may contain dozens or hundreds of lines of code.</p> <p>This is why structured programming emphasizes using only three types of statements:</p> <ol> <li>Sequential (organized through functions)</li> <li>Conditional (if, if-else, switch, etc.)</li> <li>Loops (for, while, etc.)</li> </ol> <p>The following code snippet (taken from the example above) demonstrates how creating a function instead of using a goto statement leads to a purely sequential code flow, thereby improving code clarity.</p> <pre><code>    // the code now becomes a sequntial code of three statemetns only\nint main() {\n    int result = gcd(48, 18);   \n    printf(\"GCD is: %d\\n\", result);\n    return 0;\n}\n</code></pre> <p>Note:</p> <p>In the early days, programmers found it difficult to write code without using goto. However, today we understand that avoiding goto is not a problem at all.</p>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#goto-is-not-always-bad", "title": "goto is not always bad", "text": "<ul> <li> <p>there are certain situations where using goto (or an equivalent) can simplify the code.</p> </li> <li> <p>one such example is breaking out of nested loops.</p> </li> <li> <p>while a break statement exits only the innermost loop, it can be tricky to exit multiple levels of nested loops.</p> </li> <li> <p>using a goto statement with a labeled target allows you to jump out of one or more loops easily, providing a clean way to handle such cases (which was ironically the orignal purpose of AVOIDING goto).</p> </li> </ul> break out of nested loops(without goto)break out of nested loops(WITH goto) <pre><code>#include &lt;stdio.h&gt;\n\nint main() {\n    int i, j;\n    int done = 0;  // flag to indicate when to break outer loop\n\n    for (i = 0; i &lt; 5; i++) {\n        for (j = 0; j &lt; 5; j++) {\n            printf(\"i=%d, j=%d\\n\", i, j);\n            if (i == 2 &amp;&amp; j == 3) {\n                done = 1;  // set flag\n                break;     // break inner loop\n            }\n        }\n        if (done) {\n            break; // break outer loop if flag is set\n        }\n    }\n\n    printf(\"Exited nested loops\\n\");\n    return 0;\n}\n</code></pre> <pre><code>- In this example, to break out of the outer loop, a flag variable done is used. The outer loop checks this flag, and if it\u2019s set to true, it breaks as well.\n\n- However, this approach isn\u2019t very intuitive.\n\n- The same behavior can be achieved more simply using a goto statement.\n</code></pre> <pre><code>#include &lt;stdio.h&gt;\n\nint main() {\n    int i, j;\n\n    for (i = 0; i &lt; 5; i++) {\n        for (j = 0; j &lt; 5; j++) {\n            printf(\"i=%d, j=%d\\n\", i, j);\n            if (i == 2 &amp;&amp; j == 3) {\n                goto exit_loops;  // Jump out of both loops\n            }\n        }\n    }\n\nexit_loops:\n    printf(\"Exited nested loops\\n\");\n    return 0;\n}\n</code></pre> <pre><code>- in this example using goto, breaking out of the outer loop is  more intuitive and cleaner compared to the version without goto.\n\n- therefore, the goto statement can be helpful in situations like this.\n- The same behavior can be achieved more simply using a goto statement.\n</code></pre>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#should-we-use-goto", "title": "Should we use goto?", "text": "<ul> <li> <p>A pedantic programmer might argue that goto should never be used.</p> </li> <li> <p>However, it\u2019s important to understand that goto was discouraged mainly because it often led to confusing and hard-to-follow code.</p> </li> <li> <p>In certain cases\u2014like the nested loop example above\u2014goto actually improves readability and simplifies the logic.</p> </li> <li> <p>Therefore, there\u2019s no strong reason to oppose its use outright.</p> </li> </ul>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#goto-in-go-golang-language", "title": "goto in Go (Golang) language", "text": "<ul> <li> <p>goto has actually made a come back in the case nested loop breaks in Go language.</p> </li> <li> <p>to break out of nested loops we use the \"labels\" (and not explicitly goto). However, the logic is still the same (i.e. jumps to certain label, which is what traditional goto statment does).</p> </li> </ul> Example 1: break WITHOUT labelExample 2:  break WITH labelsExample 3:  break MIDDLE loop (WITH labels) <p><pre><code>for i := 1; i &lt;= 2; i++ {\n    for j := 1; j &lt;= 3; j++ {\n        if j == 2 {\n            continue // skip when j == 2\n        }\n        fmt.Printf(\"i = %d, j = %d\\n\", i, j)\n    }\n}\n</code></pre> This code 'breaks' from the current loop only (not from all)</p> <p><pre><code>outer:\nfor i := 1; i &lt;= 3; i++ {\n    for j := 1; j &lt;= 3; j++ {\n        if j == 2 {\n            fmt.Println(\"Skipping to next outer loop iteration\")\n            continue outer // skip remaining inner loop and go to next outer i\n        }\n        fmt.Printf(\"i = %d, j = %d\\n\", i, j)\n    }\n}\n</code></pre> This code 'breaks' from the ALL loops</p> <p><pre><code>for i := 1; i &lt;= 2; i++ {\nmiddle:\n    for j := 1; j &lt;= 2; j++ {\n        for k := 1; k &lt;= 3; k++ {\n            if k == 2 {\n                fmt.Println(\"Continuing middle loop\")\n                continue middle\n            }\n            fmt.Printf(\"i=%d j=%d k=%d\\n\", i, j, k)\n        }\n    }\n}\n</code></pre> **This code 'breaks' from two loops out of three loops (hence more refined control)</p> <p>It can much more complicated to break out of selected loop by using flag variables at different levels. A cleaner logic would be to use labels (i.e. hidden goto statements)</p>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#inter-function-vs-intra-function-use-of-goto", "title": "Inter-Function vs. Intra-Function use of goto", "text": "<p><code>goto</code> was originally discouraged at the cross-function level because jumping between functions breaks modularity and disrupts structured control flow, making the code harder to understand and maintain. However, when used within a single function\u2014especially in small functions\u2014it generally doesn't harm readability and can even simplify error handling or cleanup in some cases.</p>", "tags": ["goto", "structured programming"]}, {"location": "blog/2025/08/02/is-goto-statement-dead.html#summary", "title": "Summary", "text": "<ul> <li> <p>goto is a discouraged programming construct and has become nearly obsolete in most cases since the rise of structured programming in the late 1970s.</p> </li> <li> <p>The main reason for this is its negative impact on code readability.</p> </li> <li> <p>However, in certain scenarios\u2014such as breaking out of nested loops\u2014it can actually improve readability and give finer control over program flow.</p> </li> <li> <p>A relatively new and popular language, Go (Golang), does not have traditional goto statements but supports labeled breaks, which serve a similar purpose for exiting loops.</p> </li> <li> <p>These \"labelled breaks\" in Go are intended for more localized use within functions or loops, unlike traditional goto which could jump anywhere in the program.</p> </li> <li> <p>So, while goto itself is rarely used today, its adapted form\u2014label-based breaks\u2014still finds practical use in specific situations. </p> </li> </ul> <p>Jumping ACROSS function boundaries was the primary (mis)use that led to goto being discouraged.</p>", "tags": ["goto", "structured programming"]}, {"location": "languages/golang/index.html", "title": "Golang Programming", "text": "<p>Go language is developed by Google and this site is designed to contains tutorials to quickly learn basic skills and many application samples.</p> <ul> <li> <p>Open Source &amp; Cross-Platform: Runs seamlessly on Linux, Windows, and macOS.</p> </li> <li> <p>Easy to Learn: Simple syntax, clean design \u2014 approachable like Python.</p> </li> <li> <p>Fast Compilation: Ideal for large-scale systems where build speed matters.</p> </li> <li> <p>High Performance: Execution speed is comparable to C/C++.</p> </li> <li> <p>Great for Web Backends: Widely used in scalable server-side development.</p> </li> <li> <p>Built-in Concurrency: Goroutines and channels make multitasking efficient and developer-friendly.</p> </li> <li> <p>Rich &amp; Growing Ecosystem: Standard library includes robust support for web servers, I/O, cryptography, and more.</p> </li> </ul>", "tags": ["go", "golang"]}, {"location": "languages/golang/index.html#what-it-is-not", "title": "What it is not", "text": "<ul> <li> <p>Not Primarily for System Programming: While Go is powerful, it's not designed for low-level system programming (e.g. writing OS kernels or device drivers). Languages like C, C++, and Rust offer more control over memory, hardware access, and performance tuning.</p> </li> <li> <p>Not Meant for Every Use Case: Go excels at web backends, network servers, and concurrent workloads, but may fall short in areas requiring fine-grained memory management, real-time constraints, or tight binary size control.</p> </li> </ul>", "tags": ["go", "golang"]}, {"location": "languages/golang/index.html#explore-more-topics", "title": "Explore more topics", "text": "<p>Feel free to explore various topics through navigation bar.</p>", "tags": ["go", "golang"]}, {"location": "languages/golang/01-gettingstarted.html", "title": "01-Getting Started", "text": "<pre><code>Go Installation\n\nHello World\n\nSemicolons(;) in Go\n</code></pre>"}, {"location": "languages/golang/01-gettingstarted.html#1-go-installation", "title": "1. Go Installation", "text": "Linux (Ubuntu)Windows <p>Type following in the terminal</p> <p><pre><code>sudo apt update &amp;&amp; sudo apt upgrade\nsudo apt install golang-go\n</code></pre> to check the instllation: type <code>go version</code></p> <p>If everything is OK, you should see go version information.</p> <ol> <li>Download MSI installer from Go website</li> <li>Open the MSI file you downloaded and follow the prompts to install Go. </li> </ol> <p>By default, the installer will install Go to Program Files or Program Files (x86). You can change the location as needed. </p> <ol> <li>Open the command prompt (or PowerShell)</li> </ol> <p>type <code>go version</code></p> <p>If everything is OK, you should see go version information.</p>"}, {"location": "languages/golang/01-gettingstarted.html#2-hello-world-with-print-and-println", "title": "2. Hello World with Print and Println", "text": "<p>This chapter describes how to write your first program in Go language.</p> <p>Following is a standalone program in Go</p> <p>In this exmple, we are printing some statements. We use Println and Print</p> <ul> <li>fmt.Print() prints output without a newline at the end.</li> <li>fmt.Println() prints output with a newline. </li> </ul> <p>Create a file with any name of your choice, e.g. helloGo.go and copy following contents in it.</p> Println examplePrint example <p><pre><code>//Single line comment\n\n/* \nMulti-line comments\nline 2 of comments\n*/\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    //fmt.Println() prints output with a newline. \n    fmt.Println(\"Hello World\")\n    fmt.Println(\"My name is Mujeeb\")\n}\n</code></pre> output: <pre><code>Hello World\nMy name is Mujeeb\n</code></pre></p> <p><pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    //fmt.Print() prints output without a newline at the end.\n    fmt.Print(\"Hello World\")\n    fmt.Print(\"My name is Mujeeb\")\n}\n</code></pre> output: <pre><code>Hello WorldMy name is Mujeeb\n</code></pre></p>"}, {"location": "languages/golang/01-gettingstarted.html#a-note-on-comments", "title": "A note on comments", "text": "<pre><code>Comments in Go can be single-line or multi-line, similar to how they are used in C++ or Java.\n</code></pre>"}, {"location": "languages/golang/01-gettingstarted.html#how-to-compile-and-run-the-program", "title": "How to compile and run the program", "text": "Linux (Ubuntu) <ol> <li>Open the terminal.</li> <li> <p>Compile the program by typing go build helloGo.go</p> <p>An executable file is generated with name helloGo</p> </li> <li> <p>Run the program by typing its name ./helloGo</p> </li> </ol>"}, {"location": "languages/golang/01-gettingstarted.html#3-semicolons-in-go", "title": "3. Semicolons(;) in Go", "text": "<ul> <li>Semicolons are required by the Go language (internally).  But you usually don\u2019t write it yourself \u2014 the Go compiler inserts it for you automatically during parsing.</li> </ul>"}, {"location": "languages/golang/01-gettingstarted.html#when-you-must-write-semicolons", "title": "When you MUST write semicolons", "text": "<ul> <li>If you try to write multiple statements on one line without ;, it will cause a compile error: <pre><code>x := 10 y := 20 // \u274c invalid\n\nx := 10; y := 20 // \u2705 valid but discouraged\n</code></pre></li> </ul> <p>So, in practice:</p> <ul> <li>Semicolons are required by the spec, but Go handles them for you automatically</li> <li>You should avoid writing them manually, unless you're writing multiple short statements on the same line (which is not recommended)</li> </ul>"}, {"location": "languages/golang/01-gettingstarted.html#4-points-to-remember", "title": "4. Points to remember", "text": "<ul> <li>Go comment style is same as C/C++.</li> <li>A standalone application must inclue **pacakge main\" statement on top</li> <li>fmt.Println(\"Hello World\") is equivalent of printf statement in C/C++</li> <li>Code indentation is not required, but highly recommended for readability. We can use tabs or spaces (same as in C/C++ or Java)</li> <li>for prints and some other input/output statements, golang package is fmt which must be included</li> <li>starting curly bracket { MUST be one same line as the function name. Unlike C/C++ or Java, we cannot write it to the next line.</li> <li>semicolons are optional in Go, unless you are writing multiple statements on a single line (which is  discouraged)</li> </ul> IncorrectCorrect <pre><code>func main() \n{\n    fmt.Println(\"Hello World\")\n}\n</code></pre> <pre><code>func main() {\n    fmt.Println(\"Hello World\")\n}\n</code></pre>"}, {"location": "languages/golang/01-gettingstarted.html#5-check-your-understanding", "title": "5. Check your understanding", "text": "What package should your main executable Go program be in? <p>Ans: package main</p> What is the significance of the main function in a Go program? <p>Ans: It\u2019s the entry point where program execution starts.</p> How do you import other packages into your Go file? <p>Ans: Using the import keyword followed by the package name(s). <pre><code>import (\n\"fmt\"\n\"math\"\n)\n</code></pre></p> What does fmt.Println do? <p>Ans: Prints text with a newline to the console. </p> What package is needed to use Println? <p>Ans: fmt</p> What is the difference between Print and Println from the fmt package? <p>Ans: Print doesn\u2019t add a newline; Println adds a newline at the end.</p> Is the main function mandatory for all Go programs? <p>Yes, for executable programs (i.e main package) No, for other packages</p> How do you write a comment in Go? <p>Ans: Use <code>//</code> for single-line comments, and <code>/* */</code> for multi-line comments <pre><code># single line comment: This is a comment statement\n\n/* multi-line comment\nline 2\n*/\n</code></pre></p> Can the main function take parameters or return values? <p>Ans: No, main must have no parameters or return values.</p> What are alternate ways to pass command line arguments and return code? <p>Ans: If you want to handle command-line arguments, </p> <ul> <li>use the os.Args slice instead.</li> <li>To signal an exit status, use os.Exit(code).</li> </ul> <p>(Note: They are not covered in this lesson)</p> What happens if you try to declare main with a capital letter like Main? <p>Ans: It won\u2019t be recognized as the entry point; program won\u2019t run as expected.</p> How do you run a Go program in console? <p>Ans: Use <code>go run filename.go</code> </p> <p>or build with <code>go build &lt;inputfile.go&gt;`&lt;outfile&gt;</code>and run the generated executable by typing its name in the console</p> What is wrong (if any) with the following code? <p>Ans: Go  places the opening { on the same line as the function declaration; the correct code is following. <pre><code>func main() {\n    fmt.Println(\"Hello World\")\n}\n</code></pre></p> <pre><code>func main() \n{\n    fmt.Println(\"Hello World\")\n}\n</code></pre>"}, {"location": "languages/golang/02-basics.html", "title": "02-Some Fundamentals", "text": "<ul> <li>importing packages</li> <li>creating variables </li> <li>short declarations</li> <li>constant declaration (immutable)</li> <li>zero values</li> </ul>"}, {"location": "languages/golang/02-basics.html#1-importing-packages", "title": "1. Importing packages", "text": "<ul> <li>In the previous chapter, we used a package \"import fmt\".</li> <li> <p>In Go, a package is a collection of related source files that are compiled together.</p> <p>For example, the \"fmt\" package provides functions for formatted input and output, such as fmt.Println() and fmt.Printf().</p> </li> <li> <p>In Go, a program must import a package at the beginning of the source file to access and use the functionality defined in that package.</p> </li> </ul> <pre><code>//To import a single package:\nimport \"fmt\"\n\n//To import multiple packages:\nimport (\n    \"fmt\"\n    \"math\"\n)\n</code></pre>"}, {"location": "languages/golang/02-basics.html#an-example", "title": "An example", "text": "<pre><code>package main\n\nimport (\n    \"fmt\"\n    \"math\"\n)\n\nfunc main() {\n    fmt.Println(math.Floor(2.75))\n}\n</code></pre>"}, {"location": "languages/golang/02-basics.html#2-declaring-variables", "title": "2. Declaring Variables", "text": "<p>Syntax to create a variable is <pre><code>var &lt;name&gt; &lt;type&gt;\n</code></pre></p> <p>For example, </p> DeclarationAssigning ValuesAssining and Declaring togetghar <pre><code>var quantity int\nvar height float64\nvar name string\nvar length, width int\n</code></pre> <pre><code>quantity = 23\nname \"Mujeeb\"\nlength, width = 10, 14\n</code></pre> <pre><code>//go decides on the type based on the value\nmessage := \"Ronaldo\"\nage := 25\n\n//or\nvar quantity = 23\nvar length, width = 10,14 //both are integer\nvar length, width = 10.0, 14 //can you guess types?\n</code></pre>"}, {"location": "languages/golang/02-basics.html#3-built-in-data-types", "title": "3. Built-in data types", "text": "<p>Basic types</p> <ul> <li>bool</li> <li>string</li> </ul> <p>Integer types</p> <ul> <li>int</li> <li>int8</li> <li>int16</li> <li>int32 (alias: rune)</li> <li>int64</li> <li>uint</li> <li>uint8 (alias: byte)</li> <li>uint16</li> <li>uint32</li> <li>uint64</li> <li>uintptr</li> </ul> Float types <ul> <li>float32</li> <li>float64</li> </ul> Complex types <ul> <li>complex64</li> <li>complex128</li> </ul> Alias types <ul> <li>byte (alias for uint8)</li> <li>rune (alias for int32)</li> </ul>"}, {"location": "languages/golang/02-basics.html#4-short-variable-declaration", "title": "4. Short variable declaration", "text": "<ul> <li>The short variable declaration syntax uses := to declare and initialize a variable in one concise statement.</li> <li>It automatically infers the variable\u2019s type from the value on the right-hand side. -It can only be used inside functions (not at the package level).</li> </ul> <p>Syntax <pre><code>//variableName := value\nfunc main() {\n    age := 25        // int inferred\n    fmt.Println(age) // Output: 25\n}\n</code></pre></p>"}, {"location": "languages/golang/02-basics.html#important-points-about-short-variable-declation", "title": "Important points about short variable declation", "text": "<ul> <li>Variable type is inferred automatically.</li> <li>You cannot use := without initialization (no zero value-only declarations).</li> <li>Very handy for quick and readable code inside functions.</li> <li>You cannot declare a variable without initialization</li> </ul> <p>We can change the value of the variable, but then we have to use \"=\" instead of \":=\" <pre><code>func main() {\n    x := 10          // Declare and initialize x with 10\n    fmt.Println(x)   // Output: 10\n\n    //x :=20   COMPILATION ERROR\n    x = 20           // Reassign a new value to x\n    fmt.Println(x)   // Output: 20\n}\n</code></pre></p> <pre><code>name := \"Alice\"\nname := \"Bob\" // \u274c ERROR: no new variables on left side of :=\n</code></pre>"}, {"location": "languages/golang/02-basics.html#short-declaration-outside-functions-not-allowed", "title": "'short declaration' outside functions not allowed", "text": "<ul> <li>You cannot do this at the package level (outside functions)</li> <li>At the package level (outside any function), Go requires explicit var declarations at the top level. (This point will be discussed in more details in the section of Packages later.)</li> </ul>"}, {"location": "languages/golang/02-basics.html#short-declaration-summary", "title": "'short declaration' summary:", "text": "context allowed inside functions YES outside function (e.g. package level) NO value update NO"}, {"location": "languages/golang/02-basics.html#5-constants-in-go-immutables", "title": "5. Constants in Go (Immutables)", "text": "<p>The const keyword in Go is used to declare constant values \u2014 these are values that cannot change after they're defined.</p> <pre><code>const pi = 3.14 \nconst pi float64 = 3.14159 // inferred as float64\n</code></pre>"}, {"location": "languages/golang/02-basics.html#6-zero-values", "title": "6. Zero values", "text": "<p>In Go, \"zero values\" are the default values assigned to variables when they are declared but not explicitly initialized.</p> Type Zero Value bool false int, float 0, 0.0 string empty string (not Nil) pointer, func, interface{}, map, slice, chan Nil struct Fields = zero values <p>Note:</p> <ul> <li>Some of the above data types are not explained in this chapter (such as struct, pointer...). They will be described in the subsequent chapters.</li> <li>nil is used with reference types, not value types (to be explained in coming chapters)</li> </ul>"}, {"location": "languages/golang/03-datatypes-1.html", "title": "03-Data Types Part-1", "text": "<p>This section contains information about following topics:</p> <ul> <li>data type: boolean, int, float</li> <li>signed and unsigned integers</li> <li>variables of different size (8-bit, 16-bit, so on)</li> </ul>"}, {"location": "languages/golang/03-datatypes-1.html#1-boolean-variables", "title": "1. Boolean variables", "text": "<ul> <li> <p>The bool type is one of the built-in types, and they represents boolean values \u2014 either true or false.</p> </li> <li> <p>They are cmmonly used for logical decisions, conditions, and flags (to be convered later in this tutorial series)</p> </li> </ul>"}, {"location": "languages/golang/03-datatypes-1.html#some-examples-of-boolean", "title": "Some examples of boolean", "text": "Click to view boolean example snippetsA complete exampleOutput <pre><code>//remeber that \"go\" is case sensitive...bool is not same as Bool\n\nvar isReady bool\nfmt.Println(isReady)  // false (default value)\n\n//Declaration with initialization\nvar isLoggedIn bool = true\n\n//Short variable declaration\nisAdmin := false\n\n//boolean expressions\na := 10\nb := 5\n\nisGreater := a &gt; b         // true\nisEqual := a == b          // false\nisValid := a &gt; 0 &amp;&amp; b &gt; 0  // true\n</code></pre> <pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    var flag bool = true\n    isEven := 10%2 == 0\n    isEmpty := \"\" == \"\"\n\n    fmt.Println(\"flag:\", flag)\n    fmt.Println(\"Is 10 even?\", isEven)\n    fmt.Println(\"Is string empty?\", isEmpty)\n}\n</code></pre> <pre><code>flag: true\nIs 10 even? true\nIs string empty? true\n</code></pre>"}, {"location": "languages/golang/03-datatypes-1.html#common-usages-of-bool-variables", "title": "Common usages of bool variables", "text": "Use case Example Conditional logic <code>if isAdmin { ... }</code> Loop control <code>for ok := true; ok; { ... }</code> Function return <code>func isEven(n int) bool { return n % 2 == 0 }</code> State/flags <code>vvar isConnected bool = false</code>"}, {"location": "languages/golang/03-datatypes-1.html#1-integer-variables", "title": "1. integer variables", "text": "<p>In Go, int is a built-in numeric type used to store whole numbers (integers). It supports both positive and negative values.</p> <ul> <li>It is a signed integer type (unless explicitly defined as unsigned.</li> <li>The size of int is platform-dependent:<ul> <li>32 bits on 32-bit systems</li> <li>64 bits on 64-bit systems</li> </ul> </li> </ul>"}, {"location": "languages/golang/03-datatypes-1.html#signed-integers", "title": "signed integers", "text": "Type Description Size int Platform-dependent integer 32 or 64 bits int8 8-bit signed integer \u2212128 to 127 int16 16-bit signed integer \u221232,768 to 32,767 int32 32-bit signed integer \u22122^31 to 2^31\u22121 int64 64-bit signed integer \u22122^63 to 2^63\u22121"}, {"location": "languages/golang/03-datatypes-1.html#unsinged-integers", "title": "unsinged integers", "text": "Type Description Value Range uint Platform-dependent unsigned integer 0 to 2\u00b3\u00b2\u22121 or 2\u2076\u2074\u22121 uint8 8-bit unsigned integer 0 to 255 uint16 16-bit unsigned integer 0 to 65,535 uint32 32-bit unsigned integer 0 to 4,294,967,295 uint64 64-bit unsigned integer 0 to 18,446,744,073,709,551,615"}, {"location": "languages/golang/03-datatypes-1.html#signed-and-unsigned-integer-examples", "title": "signed and unsigned integer examples", "text": "Click to view signed intA complete programunsigned intA complete example (unsinged) <pre><code>//basic example\nvar age int = 30\nbalance := -1500\nfmt.Println(\"Age:\", age)\nfmt.Println(\"Balance:\", balance)\n\n//int8 (Range: -128 to 127)\nvar temperature int8 = -20\nfmt.Println(\"Temperature:\", temperature)\n\n//int16 (Range: -32,768 to 32,767)\nvar altitude int16 = 1200\nfmt.Println(\"Altitude:\", altitude)\n\n//int32 (Range: -2,147,483,648 to 2,147,483,647)\nvar population int32 = 1500000\nfmt.Println(\"Population:\", population)\n\n//5. int64 (Range: Very large range, 64-bit)\nvar nationalDebt int64 = -900000000000\nfmt.Println(\"National Debt:\", nationalDebt)\n</code></pre> <pre><code>//a working program to demonstrate signed int (int)\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    var x int = -100\n    var y int8 = 127\n    var z int16 = -32768\n    var a int32 = 2000000\n    var b int64 = 9223372036854775807\n\n    fmt.Println(\"int:\", x)\n    fmt.Println(\"int8:\", y)\n    fmt.Println(\"int16:\", z)\n    fmt.Println(\"int32:\", a)\n    fmt.Println(\"int64:\", b)\n}\n</code></pre> <pre><code>//Basic uint Example\nvar distance uint = 150\nfmt.Println(\"Distance:\", distance)\n\n//uint8 (Range: 0 to 255)\nvar brightness uint8 = 200\nfmt.Println(\"Brightness:\", brightness)\n\n//uint16 (Range: 0 to 65,535)\nvar port uint16 = 8080\nfmt.Println(\"Port:\", port)\n\n//uint32 (Range: 0 to 4,294,967,295)\nvar views uint32 = 2500000\nfmt.Println(\"Views:\", views)\n\n//uint64 (Range: 0 to 18,446,744,073,709,551,615)\nvar totalSupply uint64 = 1000000000000000\nfmt.Println(\"Total Supply:\", totalSupply)\n</code></pre> <pre><code>//a working program to demonstrate unsigned int (uint)\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    var a uint = 100\n    var b uint8 = 255\n    var c uint16 = 60000\n    var d uint32 = 4000000000\n    var e uint64 = 1234567890123456789\n\n    fmt.Println(\"uint:\", a)\n    fmt.Println(\"uint8:\", b)\n    fmt.Println(\"uint16:\", c)\n    fmt.Println(\"uint32:\", d)\n    fmt.Println(\"uint64:\", e)\n}\n</code></pre>"}, {"location": "languages/golang/03-datatypes-1.html#3-floating-point-variables", "title": "3. floating point variables", "text": "<ul> <li>Floating-point numbers are used to represent real numbers (i.e., numbers with decimal points), including both fractions and very large/small values.</li> <li>In Go, floating-point numbers are represented using the built-in types:</li> </ul> Type Precision Range float32 ~6 decimal digits \u00b11.18\u00d710\u207b\u00b3\u2078 to \u00b13.4\u00d710\u00b3 float64 ~15 decimal digits \u00b12.23\u00d710\u207b\u00b3\u2070\u2078 to \u00b11.8\u00d710\u00b3 <p>float64 is the default type when you write a floating-point literal.</p>"}, {"location": "languages/golang/03-datatypes-1.html#floating-point-examples", "title": "floating point examples", "text": "Click to view float32A complete examplefloat64A complete example <pre><code>//Declare and initialize\nvar temperature float32 = 36.6\nfmt.Println(\"Temperature:\", temperature)\n\n//Short variable declaration\nheight := float32(5.9)\nfmt.Println(\"Height:\", height)\n\n//arithmetic operations on float\nvar a float32 = 10.5\nvar b float32 = 3.2\n\nsum := a + b        // 13.7\ndiff := a - b       // 7.3\nproduct := a * b    // 33.6\nquotient := a / b   // ~3.28125\n\nfmt.Println(\"Sum:\", sum)\nfmt.Println(\"Difference:\", diff)\nfmt.Println(\"Product:\", product)\nfmt.Println(\"Quotient:\", quotient)\n</code></pre> <pre><code>//a working program to demonstrate float32\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    var temp float32 = 37.5\n    weight := float32(65.2)\n    bmi := weight / (1.7 * 1.7) // assuming height in meters\n\n    fmt.Println(\"Temperature:\", temp)\n    fmt.Println(\"Weight:\", weight)\n    fmt.Println(\"Estimated BMI:\", bmi)\n}\n\n/* output is following:\nTemperature: 37.5\nWeight: 65.2\nEstimated BMI: 22.560553\n*/\n</code></pre> <pre><code>//declare and initaliaze\nvar temperature float64 = 36.6\nfmt.Println(\"Temperature:\", temperature)\n\n//Short variable declaration\nheight := 5.9  // inferred as float64 by default\nfmt.Println(\"Height:\", height)\n\nvar a float64 = 10.5\nvar b float64 = 3.2\n\nsum := a + b        // 13.7\ndiff := a - b       // 7.3\nproduct := a * b    // 33.6\nquotient := a / b   // ~3.28125\n\nfmt.Println(\"Sum:\", sum)\nfmt.Println(\"Difference:\", diff)\nfmt.Println(\"Product:\", product)\nfmt.Println(\"Quotient:\", quotient)\n</code></pre> <pre><code>//a working program to demonstrate float64\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    var temp float64 = 37.5\n    weight := 65.2\n    bmi := weight / (1.7 * 1.7) // assuming height in meters\n\n    fmt.Println(\"Temperature:\", temp)\n    fmt.Println(\"Weight:\", weight)\n    fmt.Println(\"Estimated BMI:\", bmi)\n}\n/* generated out is\nTemperature: 37.5\nWeight: 65.2\nEstimated BMI: 22.560553633217992\n*/\n</code></pre>"}, {"location": "languages/golang/04-datatypes-2.html", "title": "04 Data Types-2: Strings in Go", "text": ""}, {"location": "languages/golang/04-datatypes-2.html#1-two-types-of-strings", "title": "1. Two types of strings", "text": "<p>In Go, strings can be defined in two distinct ways, each offering unique benefits depending on the use-case:</p> <p>Regular Strings \u2013 defined using double quotes (\"...\")</p> <ul> <li>These support escape sequences like \\n, \\t, \\\", etc.</li> <li>Ideal for short, dynamic strings or when using special characters.</li> </ul> <p>Raw Strings \u2013 defined using backtick characters (`...`)</p> <ul> <li>These do not support escape sequences.</li> <li>Useful for multiline text, embedded code, or preserving exact formatting.</li> </ul>"}, {"location": "languages/golang/04-datatypes-2.html#2-regular-strings", "title": "2. Regular Strings", "text": "<ul> <li>Regular strings are defined within double quotes, like C/C++, Java, and other languages.</li> <li>They can contain escape characters such as \\t, \\n...</li> </ul> Escape Sequence Description Output \\n Newline Moves to next line \\t Horizontal tab Adds tab spacing \\\\ Backslash () \\ \\\" Double quote (\") \" \\' Single quote (') (used in runes) \\r Carriage return Resets cursor to line start \\b Backspace-Deletes previous char (in some terminals)"}, {"location": "languages/golang/04-datatypes-2.html#3-raw-strings", "title": "3. Raw strings", "text": "<p>They are especially helpful for writing strings that should appear visually as they are typed.</p> <ul> <li>Raw strings are enclosed in a pair of backtick characters ( `...` ).</li> <li>They do not support escape sequences \u2014 characters like \\n, \\t, or \\\\ are treated literally.</li> <li>Raw strings are useful when you want to preserve formatting exactly as written, including spacing, indentation, and line breaks.</li> </ul>"}, {"location": "languages/golang/04-datatypes-2.html#example-of-a-raw-string", "title": "Example of a raw string", "text": "<pre><code>html := `&lt;html&gt;\n  &lt;body&gt;Hello, World!&lt;/body&gt;\n&lt;/html&gt;`\n</code></pre>"}, {"location": "languages/golang/04-datatypes-2.html#example-2", "title": "Example 2", "text": "CodeOutput <pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    var s1 string = \"Hello, world!\"\n    s2 := `Line 1\n             \\n\\tLine 2\n        Line3`\n\n    fmt.Println(s1)\n    fmt.Println(s2)\n}\n</code></pre> <pre><code>Hello, world!\nLine 1\n             \\n\\tLine 2\n        Line3\n</code></pre>"}, {"location": "languages/golang/04-datatypes-2.html#why-use-raw-strings", "title": "Why use raw strings", "text": "<p>Raw strings are especially useful in modern web-based and systems programming. Go includes raw stringsto make working with complex, formatted text easier and cleaner. </p> <ul> <li>They are quite handy for embedding code such as regular expressions, HTML, JSON, or SQL, without needing escape characters.</li> <li>They simplify writing multiline strings \u2014 no need to manually insert \\n, \\t, \\ etc.</li> <li>They preserve formatting exactly as written, including spaces, indentation, and line breaks.</li> <li>They are more readable and visually clear, especially for large blocks of text.</li> </ul>"}, {"location": "languages/golang/04-datatypes-2.html#creating-variables-various-ways", "title": "Creating variables (various ways)", "text": "Click to find various examples showing variables SnippetsComplete ExampleOutput <pre><code>// create first and use later\nvar s string\ns = \"Hello, Go!\"\n\n//declar and initialize\nvar s1 string = \"Hello\"\n\n//short variable declaration: commmon in functions\ns2 := \"World\"\n\n//using backtick (raw liternals)\ns3 := `Multiline\n    raw string\n        with no escaping like \\n or \\t.`\n\n//concatenation\ns4 := \"Hello, \" + \"World!\"\n\n//Using fmt.Sprintf() for formatted strings\nname := \"Mujeeb\"\ns5 := fmt.Sprintf(\"Hello, %s!\", name)\n\n//form a byte slice\nb := []byte{72, 101, 108, 108, 111}\ns6 := string(b)  // \"Hello\"\n\n// emoji example\nemoji := \"\ud83d\ude80\u2728\"\nfmt.Println(emoji)\n</code></pre> <pre><code>package main\n\nimport (\n    \"fmt\"\n)\n\nfunc main() {\n    var s1 string\n    s1 = \"Go is fun\"\n\n    var s2 string = \"Learning Go\"\n\n    s3 := \"With short syntax\"\n\n    s4 := `This is a\n                multiline raw string.\n        Line 3`\n\n    name := \"Mujeeb\"\n    s5 := fmt.Sprintf(\"Hello, %s!\", name)\n\n    b := []byte{72, 105}\n    s6 := string(b) // \"Hi\"\n\n    r := []rune{'\ud83d\ude80', '\u2728'}\n    s7 := string(r)\n\n    fmt.Println(s1)\n    fmt.Println(s2)\n    fmt.Println(s3)\n    fmt.Println(s4)\n    fmt.Println(s5)\n    fmt.Println(s6)\n    fmt.Println(s7)\n}\n</code></pre> <pre><code>Go is fun\nLearning Go\nWith short syntax\nThis is a\n            multiline raw string.\n       Line 3\nHello, Mujeeb!\nHi\n\ud83d\ude80\u2728\n</code></pre>"}, {"location": "languages/golang/04-datatypes-2.html#4-utf-8-format-coding", "title": "4. UTF-8 Format Coding", "text": "<ul> <li>Strings in Go (both regular strings and raw strings) use UTF-8 encoding by default.</li> <li>UTF-8 is the most widely used character encoding for representing text from various languages, symbols, and special characters.</li> <li>It is a variable-length encoding, using 1 to 4 bytes per character, depending on the character's Unicode code point.</li> <li>UTF-8 is ASCII-compatible, meaning all standard ASCII characters (values 0\u2013127) have the same representation in UTF-8.</li> </ul>"}, {"location": "languages/golang/05-operators.html", "title": "05 Operators and Typecasting", "text": "<ul> <li>Arithmetic Operators</li> <li>Comparision Operators</li> <li>Logtical Operators</li> <li>Bitwise Operators</li> <li>Typecasting </li> </ul>"}, {"location": "languages/golang/05-operators.html#1-arithmetic-operators", "title": "1. Arithmetic Operators", "text": "<p>Arithmetic operations in Go (Golang) are the basic mathematical operations you can perform on numbers. These include addition, subtraction, multiplication, division, and modulus (like most languages). </p> Some examplesA full example <pre><code>////Be careful about (:= or =) assignment operations\n\na := 10\nb := 5\nsum := a + b // sum is 15\ndiff := a - b // diff is 5\nproduct := a * b // product is 50\n\n\n//integer division\na := 10\nb := 3\nquotient := a / b // quotient is 3 (integer division)\n\n//float division\nx := 10.0\ny := 3.0\nfloatQuotient := x / y // floatQuotient is 3.3333333 (float division)\n\n//Modulus (remainder) operation\na := 10\nb := 3\nremainder := a % b // remainder is 1\n</code></pre> <pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    a := 15\n    b := 4\n\n    fmt.Println(\"Addition:\", a+b)        // 19\n    fmt.Println(\"Subtraction:\", a-b)     // 11\n    fmt.Println(\"Multiplication:\", a*b)  // 60\n    fmt.Println(\"Division:\", a/b)         // 3 (integer division)\n    fmt.Println(\"Modulus:\", a%b)          // 3\n\n    // For floating point division:\n    x := 15.0\n    y := 4.0\n    fmt.Println(\"Float Division:\", x/y)  // 3.75\n}\n</code></pre>"}, {"location": "languages/golang/05-operators.html#2-comparision-operators", "title": "2. Comparision Operators", "text": "<p>Comparison operators in Go are used to compare two values and return a Boolean result (true or false). These operators are commonly used in conditions such as if statements or loops.</p> Some examplesA full example <pre><code>////Be careful about (:= or =) assignment operations\n\na := 5\nb := 5\nfmt.Println(a == b) // true\n\na := 5\nb := 3\nfmt.Println(a != b) // true\n\na := 7\nb := 5\nfmt.Println(a &gt; b) // true\n\na := 7\nb := 10\nfmt.Println(a &lt; b) // true\n\na := 7\nb := 7\nfmt.Println(a &gt;= b) // true\n\na := 7\nb := 7\nfmt.Println(a &lt;= b) // true\n</code></pre> <pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    a := 10\n    b := 20\n\n    fmt.Println(\"a == b:\", a == b)   // false\n    fmt.Println(\"a != b:\", a != b)   // true\n    fmt.Println(\"a &gt; b:\", a &gt; b)     // false\n    fmt.Println(\"a &lt; b:\", a &lt; b)     // true\n    fmt.Println(\"a &gt;= b:\", a &gt;= b)   // false\n    fmt.Println(\"a &lt;= b:\", a &lt;= b)   // true\n}\n</code></pre>"}, {"location": "languages/golang/05-operators.html#3-logical-operators", "title": "3. Logical operators", "text": "<p>Logical operators in Go let you combine or invert Boolean expressions (true or false). </p> Operator Name Description <code>&amp;&amp;</code> Logical AND True if both operands are true <code>||</code> Logical OR True if atleast ONE operand is true <code>!</code> Logical NOT Inverts the Boolean value <p>An example <pre><code>//Be careful about (:= or =) assignment operations\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    a := true\n    b := false\n\n    fmt.Println(\"a &amp;&amp; b:\", a &amp;&amp; b)  // false\n    fmt.Println(\"a || b:\", a || b)  // true\n    fmt.Println(\"!a:\", !a)          // false\n}\n</code></pre></p>"}, {"location": "languages/golang/05-operators.html#4-bitwise-operators", "title": "4. Bitwise operators", "text": "<ul> <li>Bitwise operators in Go allow you to perform operations directly on the binary representation of integers. </li> <li>These are very useful in systems programming, hardware control, flags, and performance-critical code.</li> </ul> Do not confuse with logical operators <ul> <li>logical operators (&amp;&amp;, ||, !) operate on boolean data, wherease bitwise operators (&amp;, | ) operate on bits </li> </ul> Operator Name Description <code>&amp;</code> AND 1 if both bits are 1 \\ <code>|</code> OR <code>^</code> XOR (binary) 1 if bits are different <code>^</code> NOT (unary) Inverts all bits <code>&amp;^</code> AND NOT (bit clear) Clears bits set in second operand <code>&lt;&lt;</code> Left Shift Shifts bits to the left <code>&gt;&gt;</code> Right Shift Shifts bits to the right"}, {"location": "languages/golang/05-operators.html#an-example", "title": "An example", "text": "<pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    a := 10 // binary: 00001010\n    b := 6  // binary: 00000110\n\n    fmt.Println(\"a &amp; b:\", a&amp;b)   // 2  -&gt; 00001010 &amp; 00000110 = 00000010  // Bitwise AND\n    fmt.Println(\"a | b:\", a|b)   // 14 -&gt; 00001010 | 00000110 = 00001110  // Bitwise OR\n    fmt.Println(\"a ^ b:\", a^b)   // 12 -&gt; 00001010 ^ 00000110 = 00001100  // Bitwise XOR\n    fmt.Println(\"^a   :\", ^a)    // -11 -&gt; ^00001010 = 11110101           // Bitwise NOT (inversion)\n    fmt.Println(\"a &amp;^ b:\", a&amp;^b) // 8  -&gt; 00001010 &amp;^ 00000110 = 00001000 // Bit Clear (AND NOT)\n    fmt.Println(\"a &lt;&lt; 1:\", a&lt;&lt;1) // 20 -&gt; 00001010 &lt;&lt; 1 = 00010100        // Left Shift (\u00d72)\n    fmt.Println(\"a &gt;&gt; 1:\", a&gt;&gt;1) // 5  -&gt; 00001010 &gt;&gt; 1 = 00000101        // Right Shift (\u00f72)\n}\n</code></pre>"}, {"location": "languages/golang/05-operators.html#5-typecasting-type-conversion", "title": "5. Typecasting (type conversion)", "text": "<p>Typecasting (more properly called type conversion in Go) is the process of converting a value of one data type into another. This is useful when you want to assign a value from one type to a variable of a different type or perform operations that require matching types.</p>"}, {"location": "languages/golang/05-operators.html#implicit-typecasting", "title": "Implicit typecasting", "text": "<p>Implicit typecasting (also called implicit conversion) is when a programming language automatically converts a value from one data type to another without you having to write extra code.</p> Implicit type conversion example <pre><code>var a int = 42          // int literal 42 implicitly converted to int\nvar b float64 = 42      // int literal 42 implicitly converted to float64\nvar c byte = 42         // int literal 42 implicitly converted to byte\n\nvar x float32 = 3.14    // floating-point literal implicitly converted to float32\nvar y float64 = 3.14    // floating-point literal implicitly converted to float64\n\nlet x = 5;       // integer\nlet y = 3.14;\n\n#IMPORTANT\nlet z = x + y;   // implicit conversion of x (int) to float for addition\n</code></pre>"}, {"location": "languages/golang/05-operators.html#explicity-typecasting", "title": "Explicity typecasting", "text": "<p>Explicit typecasting (or explicit type conversion) is when the programmer manually converts a value from one type to another by specifying the target type in the code.</p> <p>syntax T(value)</p> Explicity type conversion example <pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    var i int = 42\n    var f float64 = float64(i) // int \u2192 float64\n    fmt.Println(f)             // Output: 42\n\n    var x float64 = 3.99\n    var y int = int(x) // float64 \u2192 int (decimal truncated)\n    fmt.Println(y)     // Output: 3\n\n    var b byte = byte(i) // int \u2192 byte\n    fmt.Println(b)       // Output: 42\n}\n</code></pre>"}, {"location": "languages/golang/05-operators.html#some-pitfalls-of-typecasting", "title": "Some pitfalls of typecasting", "text": "<p>Here are some common pitfalls of explicit typecasting</p> <ul> <li> <p>Loss of Data: Converting from a larger or more precise type to a smaller or less precise type (e.g., float64 to int) truncates or loses information. Example: int(3.99) becomes 3, decimal part lost.</p> </li> <li> <p>Overflow / Underflow: Converting a value that doesn't fit into the target type\u2019s range can cause unexpected results. Example: Casting int(300) to byte results in overflow because byte is 0\u2013255.</p> </li> <li> <p>Silent Errors: Typecasting won\u2019t raise errors or warnings when data loss or overflow occurs; it just happens silently.</p> </li> <li> <p>Unexpected Sign Changes: Casting between signed and unsigned types can change the sign and produce surprising results.</p> </li> <li> <p>Performance Overhead: Although generally small, unnecessary or excessive conversions can add performance cost.</p> </li> <li> <p>Code Readability: Excessive explicit casting can make code harder to read and understand.</p> </li> </ul>"}, {"location": "languages/golang/05-operators.html#finding-type-of-a-variable", "title": "Finding type of a variable", "text": "<p>In Go, there are two common ways to check or print the type of a variable:</p> <ol> <li>reflect.TypeOf(x)</li> <li>fmt.Printf(\"%T\", x)</li> </ol>"}, {"location": "languages/golang/05-operators.html#reflect-pacakge", "title": "\"reflect\" pacakge", "text": "<p>What is reflect package</p> <p>The reflect package in Go provides runtime reflection, which means it allows a program to inspect and manipulate values, types, and even structures at runtime, even if you don\u2019t know their exact types when writing the code.</p> <p>Type Inference</p> Basic Examplesreflect.TypeOf(x)fmt.Printf(\"%T\", x) <pre><code>const pi = 3.14\n\nvar a float32 = pi     // pi becomes float32\nvar b float64 = pi     // pi becomes float64\nvar c complex128 = pi  // pi becomes complex128 (real part)\n</code></pre> <pre><code>package main\n\nimport (\n    \"fmt\"\n    \"reflect\"\n)\n\nconst pi = 3.14\n\nfunc main() {\n    var a float32 = pi\n    fmt.Println(\"Type of a (after assigning pi):\", reflect.TypeOf(a)) // float32\n\n    var b float64 = pi\n    fmt.Println(\"Type of b (after assigning pi):\", reflect.TypeOf(b)) // float64\n\n    var c complex128 = pi\n    fmt.Println(\"Type of c (after assigning pi):\", reflect.TypeOf(c)) // complex128\n}\n</code></pre> <pre><code>package main\n\nimport \"fmt\"\n\nconst pi = 3.14\n\nfunc main() {\n    var a float32 = pi\n    fmt.Printf(\"Type of a (after assigning pi): %T\\n\", a) // float32\n\n    var b float64 = pi\n    fmt.Printf(\"Type of b (after assigning pi): %T\\n\", b) // float64\n\n    var c complex128 = pi\n    fmt.Printf(\"Type of c (after assigning pi): %T\\n\", c) // complex128\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html", "title": "06 Conditions and Loops", "text": "<ul> <li>if statements</li> <li>switch statements</li> <li>loops</li> <li>break and continue</li> </ul> <p>To understand this topic, make sure that you are familiar with the concept of boolean data types, which are described in more details in boolean data types</p>"}, {"location": "languages/golang/06-if-loops.html#1-if-statements", "title": "1. If statements", "text": "<p>The if statement in Go is used to execute code conditionally\u2014only when a given boolean expression is true.</p> Syntaxif Examplesif-else ExamplesIncorrect syntax <pre><code>if condition {\n    // code to execute if condition is true\n}\n</code></pre> <pre><code>if x &gt; 0 {\n    fmt.Println(\"x is positive\")\n}\n\n//conditions can be put within (), but this is optional\nif (x &gt; 0) {\n    fmt.Println(\"x is positive\")\n}\n</code></pre> <pre><code>if age &gt;= 18 {\n    fmt.Println(\"You are an adult.\")\n} else {\n    fmt.Println(\"You are a minor.\")\n}\n</code></pre> <pre><code>//INCORRECT because no {} (it works in C, but not in GO)\nif (x &gt; 0) \n    fmt.Println(\"x is positive\")\n\n//corrected is following (must use curly brackets to enclose the code block)\nif (x &gt; 0) {\n    fmt.Println(\"x is positive\")\n}\n\n//correct\nif x &gt; 0 {\n    fmt.Println(\"x is positive\")\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#if-else-statements", "title": "if-else statements", "text": "<p>The if-else statement lets your program choose between two paths based on a condition.</p> <ul> <li>If the condition is true, the code inside the if block runs.</li> <li>Otherwise (condition is false), the code inside the else block runs.</li> </ul> Syntaxif-else Examples <pre><code>if condition {\n    // run this if condition is true\n} else {\n    // run this if condition is false\n}\n</code></pre> <pre><code>age := 20\n\nif age &gt;= 18 {\n    fmt.Println(\"You are an adult.\")\n} else {\n    fmt.Println(\"You are a minor.\")\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#if-else-ladder-chain", "title": "if-else ladder (chain)", "text": "<p>An if-else ladder (also called an if-else-if chain) is a series of multiple conditions checked one after another.</p> <ul> <li>The program tests the first condition.</li> <li>If it\u2019s false, it moves to the next condition.</li> <li>This continues until one condition is true, or it reaches the final else block (which runs if all conditions are false).</li> </ul> SyntaxExample <pre><code>if condition1 {\n// code if condition1 is true\n} else if condition2 {\n    // code if condition2 is true\n} else if condition3 {\n    // code if condition3 is true\n} else {\n    // code if none of the above conditions are true\n}\n</code></pre> <pre><code>score := 75\n\nif score &gt;= 90 {\n    fmt.Println(\"Grade: A\")\n} else if score &gt;= 80 {\n    fmt.Println(\"Grade: B\")\n} else if score &gt;= 70 {\n    fmt.Println(\"Grade: C\")\n} else if score &gt;= 60 {\n    fmt.Println(\"Grade: D\")\n} else {\n    fmt.Println(\"Grade: F\")\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#switch-statement", "title": "switch statement", "text": "<ul> <li> <p>A switch statement in Go is like an if-else ladder\u2014both let you choose between multiple options based on conditions.</p> </li> <li> <p>But a switch is usually clearer and easier to read when you\u2019re comparing one value against many possible cases.</p> </li> <li> <p>The default case in a switch works like the final else in an if-else ladder\u2014it runs when none of the other cases match.</p> </li> </ul> SyntaxExample <pre><code>switch expression {\ncase value1:\n    // code if expression == value1\ncase value2:\n    // code if expression == value2\ndefault:\n    // code if no case matches\n}\n</code></pre> <pre><code>day := \"Tuesday\"\nswitch day {\ncase \"Monday\":\n    fmt.Println(\"Start of the week\")\ncase \"Tuesday\":\n    fmt.Println(\"Second day\")\ncase \"Friday\":\n    fmt.Println(\"Almost weekend!\")\ndefault:\n    fmt.Println(\"Just another day\")\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#when-to-use-if-else-and-when-to-use-switch", "title": "When to use if-else and when to use switch?", "text": "<p>Use if-else for complex conditions or ranges; use switch when comparing one value against many fixed options for cleaner, easier-to-read code.</p>"}, {"location": "languages/golang/06-if-loops.html#2-select-statement", "title": "2. select statement", "text": "<p>select statements in GO are used for  concurrency to wait on multiple channel operations. It\u2019s like a switch but for channels. We will cover this topic in the chapter on concurrency</p>"}, {"location": "languages/golang/06-if-loops.html#3-loops-in-go", "title": "3. Loops in Go", "text": "<p>Loops are statements which are used to repeat a block of code multiple times until a condition is met. They help automate repetitive tasks.</p>"}, {"location": "languages/golang/06-if-loops.html#for-loops", "title": "for loops", "text": "<ul> <li>IMPORTANT: Go language has only ONE type of loop construct (i.e. for loops);  In other words Go doesn\u2019t have while, do-while, or foreach. Everything is done using for.</li> <li>while and do-while type of loop constructs as found in other languages are implemented using for loops only. </li> </ul> fixed iterationswhile-styleddo-while-styled <pre><code>//to execute a code block for a fixed number of times\nfor i := 0; i &lt; 5; i++ {\n    fmt.Println(i)\n}\n</code></pre> <pre><code>//to perform a loop until a certain condition is met\n//number of iterations may not be known in advance\ni := 0\nfor i &lt; 5 {\n    fmt.Println(i)\n    i++\n}\n</code></pre> <pre><code>//to perform a loop until a certain condition is met\n//number of iterations may not be known in advance\n//ADDITIONALLY, code must be executed ATLEAST ONCE\n\ni := 0\nfor {\n    fmt.Println(\"i =\", i)\n    i++\n    if i &gt;= 5 {\n        break\n    }\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#when-to-use-which-style", "title": "when to use which style", "text": "<ol> <li>traditional for loop:  execute a code block for a fixed number of times</li> <li>while-styled loop: to perform a loop until a certain condition is met. The number of iterations may not be known in advance</li> <li>while-styled loop: to perform a loop until a certain condition is met. The number of iterations may not be known in advance. ADDITIONALLY, code must be executed ATLEAST ONCE.</li> </ol>"}, {"location": "languages/golang/06-if-loops.html#infinite-loops", "title": "infinite loops", "text": "Basic exampleMore examples <pre><code>for {\n    fmt.Println(\"loop forever\")\n}\n</code></pre> <pre><code>//EXAMPLE 1: break out of infinite loop when a condition is met\ni := 0\nfor {\n    if i &gt;= 5 {\n        break\n    }\n    fmt.Println(i)\n    i++\n}\nfmt.Println(\"Loop ended\")\n\n//Example 2\ni := 0\nfor {\n    i++\n    if i%2 == 0 {\n        continue // Skip even numbers\n    }\n    fmt.Println(i)\n    if i &gt;= 9 {\n        break\n    }\n}\n\n//Example 3: time delay \nfor {\n    fmt.Println(\"Tick\")\n    time.Sleep(1 * time.Second)\n}\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#nested-loops", "title": "Nested loops", "text": "<ul> <li>A nested loop is a loop placed inside another loop. It\u2019s used when you need to repeat actions in a multi-level structure (like rows and columns).</li> <li>(No of iterations becomes N X M: where N is the outer loop count, and M is the inner loop count)</li> </ul>"}, {"location": "languages/golang/06-if-loops.html#example-multiplication-table-1-to-3", "title": "Example- Multiplication Table (1 to 3)", "text": "<pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    for i := 1; i &lt;= 3; i++ {\n        for j := 1; j &lt;= 3; j++ {\n            fmt.Printf(\"%d x %d = %d\\n\", i, j, i*j)\n        }\n    }\n}\n- The outer loop (i) runs from 1 to 3.\n- For each value of i, the inner loop (j) runs from 1 to 3.\n- The inner loop completes all its iterations for every single iteration of the outer loop.\n</code></pre>"}, {"location": "languages/golang/06-if-loops.html#4-some-fine-points-about-loops", "title": "4. Some fine points about loops", "text": ""}, {"location": "languages/golang/06-if-loops.html#break-exit-the-loop-statement-in-a-loop", "title": "break (exit the loop) statement  in a loop", "text": "<p>Example of break <pre><code>for i := 0; i &lt; 10; i++ {\n    if i == 3 {\n        break\n    }\n    fmt.Println(i)\n}\n\n//Example 2: Find the first match in a list\n//Efficiently exit when you find the first match.\nnums := []int{3, 7, 9, 12, 18}\nfor _, n := range nums {\n    if n%6 == 0 {\n        fmt.Println(\"Found divisible by 6:\", n)\n        break\n    }\n}\n</code></pre></p>"}, {"location": "languages/golang/06-if-loops.html#continue-statement-in-a-loop", "title": "continue statement in a loop", "text": "<p>The continue statement is used to skip the rest of the current loop iteration and move directly to the next iteration.</p> <p>Example of continue <pre><code>for i := 1; i &lt;= 5; i++ {\n    if i%2 == 0 {\n        continue\n    }\n    fmt.Println(i) // prints only odd numbers\n}\n</code></pre></p>"}, {"location": "languages/golang/06-if-loops.html#breaking-out-of-nested-loops-ie-multiple-loop", "title": "breaking out of nested loops (i.e. MULTIPLE loop)", "text": "<ul> <li>break statement exits from the current loop only (so if we currently in the code of inner loop, only inner loop will be exited. </li> <li>In many situations, we would like to break out of ALL loop. </li> <li>We achieve this by using a \"label\"</li> </ul> Example: CorrectERROR (important) Breaking out of two inner loops (but not the outermost) <p><pre><code>package main\nimport \"fmt\"\n\nfunc main() {\nouter: // label is here\n    for i := 1; i &lt;= 3; i++ {\n        for j := 1; j &lt;= 3; j++ {\n            if i == 2 &amp;&amp; j == 2 {\n                fmt.Println(\"Breaking out of both loops\")\n                break outer // exits the outer loop entirely\n            }\n            fmt.Printf(\"i = %d, j = %d\\n\", i, j)\n        }\n    }\n\n    fmt.Println(\"This runs after both loops\")\n}\n</code></pre> Following is the output <pre><code>i = 1, j = 1\ni = 1, j = 2\ni = 1, j = 3\ni = 2, j = 1\nBreaking out of both loops\nThis runs after both loops\n</code></pre></p> <pre><code>import \"fmt\"\n\nfunc main() {\nouter: // label is here\n    //print(\"loop starts\") : ERROR...CANNOT PUT A STATEMENT BETWEENA LABLE AND LOOP\n    for i := 1; i &lt;= 3; i++ {\n        for j := 1; j &lt;= 3; j++ {\n            if i == 2 &amp;&amp; j == 2 {\n                fmt.Println(\"Breaking out of both loops\")\n                break outer // exits the outer loop entirely\n            }\n            fmt.Printf(\"i = %d, j = %d\\n\", i, j)\n        }\n    }\n\n    fmt.Println(\"This runs after both loops\")\n}\n</code></pre> <pre><code>package main\n\nimport \"fmt\"\n\nfunc main() {\n    for x := 1; x &lt;= 2; x++ {\n        fmt.Println(\"Outer loop x =\", x)\n\n    middle:\n        for y := 1; y &lt;= 3; y++ {\n            for z := 1; z &lt;= 3; z++ {\n                if y == 2 &amp;&amp; z == 2 {\n                    fmt.Println(\"Breaking from middle and inner loops\")\n                    break middle // only breaks middle and inner\n                }\n                fmt.Printf(\"  y = %d, z = %d\\n\", y, z)\n            }\n        }\n    }\n\n    fmt.Println(\"Done.\")\n}\n</code></pre> <p>Output is: <pre><code>Outer loop x = 1\n  y = 1, z = 1\n  y = 1, z = 2\n  y = 1, z = 3\n  y = 2, z = 1\nBreaking from middle and inner loops\nOuter loop x = 2\n  y = 1, z = 1\n  y = 1, z = 2\n  y = 1, z = 3\n  y = 2, z = 1\nBreaking from middle and inner loops\nDone.\n</code></pre></p> <p>Note:</p> <ul> <li>The outer loop does not restart (AFTER the break statement). It ends right after break outer is called.</li> <li>Execution resumes after the whole loop block.</li> <li>do not be confused about the position of label. It is written before the loops, but the after breaking, the loops will not be executed</li> </ul>"}, {"location": "languages/golang/06-if-loops.html#continue-in-nested-loops-multiple-loops", "title": "continue in nested loops (multiple loops)", "text": "Example 1: Skip CURRENT loop onlyExample 2:  Skip ALL loopsExample 3:  Skip FEW loops <p><pre><code>for i := 1; i &lt;= 2; i++ {\n    for j := 1; j &lt;= 3; j++ {\n        if j == 2 {\n            continue // skip when j == 2\n        }\n        fmt.Printf(\"i = %d, j = %d\\n\", i, j)\n    }\n}\n</code></pre> Output: <pre><code>i = 1, j = 1\ni = 1, j = 3\ni = 2, j = 1\ni = 2, j = 3\n</code></pre></p> <pre><code>outer:\nfor i := 1; i &lt;= 3; i++ {\n    for j := 1; j &lt;= 3; j++ {\n        if j == 2 {\n            fmt.Println(\"Skipping to next outer loop iteration\")\n            continue outer // skip remaining inner loop and go to next outer i\n        }\n        fmt.Printf(\"i = %d, j = %d\\n\", i, j)\n    }\n}\n</code></pre> <p>Output: <pre><code>i = 1, j = 1\nSkipping to next outer loop iteration\ni = 2, j = 1\nSkipping to next outer loop iteration\ni = 3, j = 1\nSkipping to next outer loop iteration\n</code></pre></p> <pre><code>for i := 1; i &lt;= 2; i++ {\nmiddle:\n    for j := 1; j &lt;= 2; j++ {\n        for k := 1; k &lt;= 3; k++ {\n            if k == 2 {\n                fmt.Println(\"Continuing middle loop\")\n                continue middle\n            }\n            fmt.Printf(\"i=%d j=%d k=%d\\n\", i, j, k)\n        }\n    }\n}\n</code></pre> <p>Output: <pre><code>i=1 j=1 k=1\nContinuing middle loop\ni=1 j=2 k=1\nContinuing middle loop\ni=2 j=1 k=1\nContinuing middle loop\ni=2 j=2 k=1\nContinuing middle loop\n</code></pre></p>"}, {"location": "languages/golang/06-if-loops.html#range-statement-in-loops", "title": "range statement in loops", "text": "<p>This topic will be covered in chapter of \"Collections\" later.</p>"}, {"location": "tutorials/docker/docker-hello.html", "title": "Hello Docker", "text": "<p>Writing a Python Application</p> <p>In this section, we build a simple Docker application that displays a message 100 times on the screen with a delay of one second. </p> <p>While it's not a very useful app, it serves to demonstrate the basic concept clearly.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#1-directory-structure", "title": "1. Directory structure", "text": "<p>We create a folder structure like this:</p> <p>(a minimum docker application has two files. i)applicaiton code, and ii) Docker file) <pre><code>hello-python-docker/\n\u251c\u2500\u2500 Dockerfile          #docker configuration file\n\u251c\u2500\u2500 hello_world.py      #contains application code\n\u2514\u2500\u2500 requirements.txt    #(optional) file to install extra modules which are not part of base package\n</code></pre></p> <p>Create he directory and files (empty) as shown below: <pre><code>mkdir hello_python_docker   #create a folder\n\ncd hello_python_docker      #python file that prints a message\n\ntouch hello_world.py\n\ntouch Dockerfile            #docker build instructions\n\ntouch requirements.txt      # (optional) dependencies such as required python modules\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#2-file-contents", "title": "2. File contents", "text": "<p>A Docker container must include the application code, which is its fundamental purpose. In addition to the code, it can also contain build tools, runtime environments, and configuration files \u2014 these will be explained in the next section.</p> <p>Below is an example of the application code that we are using in this example. </p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#essential-item-1-application-code", "title": "Essential item 1: Application code", "text": "<p><code>hello_world.py</code> <pre><code>import time\n\nfor i in range(1, 101):\n    print(f\"hello world - from a docker app-{i}\")\n    time.sleep(1)  # wait for 1 second\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#essential-item-2-dockerfile", "title": "Essential item 2: Dockerfile", "text": "<p>A Dockerfile is a script that defines how to build a Docker image. It specifies the following:</p> <pre><code>i) the base image\nii) the application code\niii) required dependencies\niv) configuration needed to run the application\n</code></pre> <p>In the simple example below, we are covering only the first two items:  (the base image and the application)</p> <p><code>Dockerfile</code> <pre><code># Use official Python base image\nFROM python:3.11-slim\n\n# Set working directory\nWORKDIR .\n\n# Copy source code\nCOPY hello_world.py .\nCOPY requirements.txt ./\n\n# Install dependencies (if any)\nRUN pip install --no-cache-dir -r requirements.txt\n\n# Run the app\nCMD [\"python\", \"./hello_world.py\"]\n</code></pre></p> <p>Brief Description of Dockerfile Instructions:</p> <pre><code>FROM python:3.11-slim\nSets the base image for the container. Your application code and other configurations will be layered on top of this.\n\nCOPY main.py .\nCopies the main.py file from your local directory into the Docker image.\nNote: If your app includes more files or folders, you need to copy those too.\n\nWORKDIR .\nSets the working directory inside the container \u2014 this is where commands will run from.\n\nRUN pip install --no-cache-dir -r requirements.txt\nInstalls the Python dependencies listed in requirements.txt using pip.\n\nCMD [\"python\", \"./hello_world.py\"]\nDefines the default command that runs when the container starts \u2014 in this case, it runs the Python script.\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#3-base-image-the-starting-container", "title": "3. Base image (the starting container)", "text": "<p>The base image is the foundational container used to host an application. Additional elements, such as modules and dependencies, are added as needed, along with any necessary configuration settings.</p> <p></p> <p>In this example, we are using a Python image as the base image to provide the runtime environment for our application.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#4-build-and-run", "title": "4. Build and run", "text": "<ul> <li> <p>Change directory Make sure that you are in the folder \"hello_python_docker\" <pre><code>cd ~/hello-python-docker\n</code></pre></p> </li> <li> <p>Build the docker (container) <pre><code>sudo docker build -t my_first_docker .\n</code></pre> The resulting Docker image is saved locally on your system \u2014 not as a file but inside Docker\u2019s internal storage. <pre><code>sudo docker images\n</code></pre> Output is: <pre><code>REPOSITORY        TAG       IMAGE ID       CREATED         SIZE\nmy_first_docker   latest    d4f0787c8afb   2 minutes ago   141MB\n</code></pre></p> </li> <li> <p>Run the docker (the flag -it is important here... more on this later) <pre><code>sudo docker run -it my_first_docker\n</code></pre> Output: <pre><code>hello world - from a docker app-1\nhello world - from a docker app-2\nhello world - from a docker app-3\n......\n</code></pre></p> </li> </ul>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#5-migrate-to-another-machine", "title": "5. Migrate to another machine", "text": "<p>Once docker image is ready, you can export it to a file, so that it can be trasferred to any machine where it can be executed.</p> <pre><code>sudo docker save -o my_first_docker.tar my_first_docker\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#run-into-another-machine", "title": "Run into another machine", "text": "<ul> <li>Create a docker image file (see the above section \"exporting the docker image\")</li> <li>Transfer to another machine (via network, usb, etc.)</li> <li>load the image into the target machine <pre><code>sudo docker load -i my_first_docker.tar\n</code></pre></li> <li> <p>verify that the image is properly imported. <pre><code>sudo docker images\n</code></pre></p> </li> <li> <p>Run the docker application. <pre><code>sudo docker run -it my_first_docker\n</code></pre></p> </li> </ul>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-hello.html#6-run-multiple-instances", "title": "6. Run multiple instances", "text": "<p>As mentioned earlier, that a docker is an indepdent container. </p> <p>Once created, a docker can run many instances. Following instructions show how to run a docker multiple (twice) in the same machine.</p> <p><code>Open Terminal 1</code> <pre><code>sudo docker -it run my_first_docker\n</code></pre></p> <p><code>Open Terminal 2</code> <pre><code>sudo docker -it run my_first_docker\n</code></pre></p> <p>Both will be running the same program and each will be displaying their own message count.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html", "title": "Getting Started with Docker", "text": "<p>Docker is a tool (primarily a linux-based) that lets you package your application and everything it needs to run into a single container, so it works the same on any computer.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#1-what-is-a-docker", "title": "1. What is a docker", "text": "<p>Consider a scenario:</p> <p>There is a linux machine with following configuration.</p> <ul> <li>Ubuntu Linux 22.04</li> <li>Python 3.10</li> <li>OpenCV version 4.4</li> </ul> <p>Now you wnat to run an application about robotic vision which required different set of tools as follows:</p> <ul> <li>Ubuntu Linux 22.04</li> <li>Python 3.12</li> <li>OpenCV version 4.2 (4.4 is not compatible with our robotic application)</li> </ul> <p></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#2-we-create-an-isolated-container", "title": "2. We create an ISOLATED container", "text": "<p>The ubunutu machine is not only running many other applications besides this new application robotic vision. By changing the python verion and OpenCV version may break other applications.</p> <p>So what to do in this case? We create an ISOLATED space in which we run new application alongwith all necessary tools and configuration settings.</p> <p>This new isolated space is called a container (or docker).</p> <p></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#3-multiple-docker-containers", "title": "3. Multiple docker containers", "text": "<p>This idea can be extended to include many dockers containers in a single machine, as shown below. In each case, we can chose different tools, version and configurations.</p> <p></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#4-docker-installation", "title": "4. Docker installation", "text": "<p>Docker is an application that enables the creation of isolated environments called containers. If Docker is not installed on your system, follow these steps to install it:</p> <p>You can check if docker is installed or not: <pre><code>docker --version\n</code></pre> if you see an out like docker command not found, then following the steps below.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#step-1-install-dependencies", "title": "Step 1: Install dependencies", "text": "<pre><code>sudo apt update\nsudo apt install \\\n    ca-certificates \\\n    curl \\\n    gnupg \\\n    lsb-release -y\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#step-2-add-dockers-official-gpg-key", "title": "Step 2:  Add Docker\u2019s official GPG key", "text": "<pre><code>sudo mkdir -p /etc/apt/keyrings\ncurl -fsSL https://download.docker.com/linux/debian/gpg | \\\n    sudo gpg --dearmor -o /etc/apt/keyrings/docker.gpg\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#step-3-add-dockers-repository", "title": "Step 3: Add Docker's repository", "text": "<ul> <li>Find debian codename by <code>lsb_release -c</code> (code name can be \"bookwork\" or \"buster\", or \"bullseye\" etc.) </li> <li>$(lsb_release -cs) is replaced with your Debian codename (e.g., bullseye, bookworm):</li> </ul> General CommandDebian (Bookworm) Command <pre><code>echo \\\n  \"deb [arch=$(dpkg --print-architecture) \\\n  signed-by=/etc/apt/keyrings/docker.gpg] \\\n  https://download.docker.com/linux/debian \\\n  $(lsb_release -cs) stable\" | \\\n  sudo tee /etc/apt/sources.list.d/docker.list &gt; /dev/null\n</code></pre> <pre><code>echo \\\n  \"deb [arch=$(dpkg --print-architecture) \\\n  signed-by=/etc/apt/keyrings/docker.gpg] \\\n  https://download.docker.com/linux/debian \\\n  bookworm stable\" | \\\n  sudo tee /etc/apt/sources.list.d/docker.list &gt; /dev/null\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#step-4-install-docker", "title": "Step 4: Install docker", "text": "<pre><code>sudo apt update\nsudo apt install docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin -y\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#step-5-verify-installation", "title": "Step 5: Verify installation", "text": "<pre><code>docker --version\n</code></pre> <p>You should see an output like: <pre><code>Docker version 28.3.3, build 980b856\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-installation.html#5-summary", "title": "5. Summary", "text": "<ul> <li> <p>Docker is a tool that allows multiple applications to run in isolation from each other on the same machine.</p> </li> <li> <p>Each application is packaged along with its code and the tools needed to run it, ensuring consistency.</p> </li> <li> <p>If one Docker container fails, it does not affect other running containers.</p> </li> <li> <p>Applications can be easily moved across machines since everything needed to run them is bundled together, eliminating the need for separate installations and configurations.</p> </li> </ul>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html", "title": "Docker command reference", "text": "", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#1-docker-network-commands", "title": "1. Docker network commands", "text": "", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#create-networks", "title": "Create networks", "text": "Create networks command description Example <code>docker network create &lt;network_name&gt;</code> Create a custom bridge network <code>docker network create my_network-A</code> <code>docker network create --driver &lt;driver&gt; &lt;network_name&gt;</code> Specify a network driver (e.g., bridge, overlay, macvlan) <code>docker network create --driver overlay my_overlay_net-A</code> <code>docker network create -d bridge my-bridge-net</code> Same as above using -d shorthand <code>docker network create -d bridge my-bridge-net-A</code> <code>docker network create --subnet=192.168.100.0/24 custom_net</code> Create a network with a custom subnet <code>docker network create --subnet=192.168.100.0/24 my_subnet_net-A</code>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#inspect-list-networks", "title": "Inspect &amp; list networks", "text": "Inspect &amp; List Networks command description Example <code>docker network ls</code> List all Docker networks <code>docker network ls</code> <code>docker network inspect &lt;network_name&gt;</code> Show detailed info (subnets, containers, etc.) <code>docker network inspect bridge</code>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#remove-networks", "title": "Remove networks", "text": "Remove command description Example <code>docker network rm &lt;network_name&gt;</code> Remove a network by name <code>docker network rm my_custom_net</code> <code>docker network rm net1 net2</code> Remove multiple networks <code>docker network rm net1 net2</code> <code>docker network prune</code> Remove all unused (dangling) networks <code>docker network prune</code>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#connect-and-disconnect-containers", "title": "Connect and disconnect containers", "text": "Remove command description Example <code>docker network connect &lt;network_name&gt; &lt;container_name&gt;</code> Attach a container to an existing network <code>docker network connect my_custom_net my_container</code> <code>docker network disconnect &lt;network_name&gt; &lt;container_name&gt;</code> Detach a container from a network <code>docker network disconnect my_custom_net my_container</code>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#gateways", "title": "Gateways", "text": "Gateways command description docker network create --subnet=192.168.50.0/24 --gateway=192.168.50.1 my_advanced_net Create a network with a specific IP range and gateway", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#2-container-commands", "title": "2. Container commands", "text": "Container commands command description Example docker run [options]  Create and start a new container docker run -d --name myapp nginx docker ps List running containers docker ps docker ps -a List all containers (including stopped) docker ps -a docker stop  Stop a running container docker stop myapp docker start  Start a stopped container docker start myapp docker restart  Restart a container docker restart myapp docker rm  Remove a container (must be stopped) docker rm myapp docker logs  Show logs of a container docker logs myapp docker exec -it  Run a command inside a running container docker exec -it myapp bash docker inspect  Show detailed info about container docker inspect myapp docker commit  Create new image from container changes docker commit myapp myapp_image docker top  Show running processes inside container docker top myapp docker stats Show live resource usage of containers docker stats docker pause  Pause container processes docker pause myapp docker unpause  Unpause container docker unpause myapp", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#docker-run-command-options", "title": "<code>docker run</code> command options", "text": "run command options option description Example <code>-d</code> Run container in detached (background) mode <code>docker run -d nginx</code> <code>--name</code> Give the container a custom name <code>docker run --name web nginx</code> <code>-p &lt;host&gt;:&lt;container&gt;</code> Map ports from host to container <code>docker run -p 8080:80 nginx</code> <code>-v &lt;host&gt;:&lt;container&gt;</code> Mount a volume (host \u2192 container) <code>docker run -v /my/html:/usr/share/nginx/html nginx</code> <code>-e &lt;key&gt;=&lt;value&gt;</code>Set environment variables <code>docker run -e MYSQL_ROOT_PASSWORD=secret mysql</code> <code>--network &lt;network&gt;</code> Connect to a specific Docker network <code>docker run --network=my_net nginx</code> <code>--rm</code> Automatically remove container when it exits <code>docker run --rm alpine echo \"Hello\"</code> <code>--it</code> Run in interactive mode (tty) <code>docker run -it ubuntu bash</code> <code>--restart &lt;policy&gt;</code> Set restart policy (no, always, on-failure) <code>docker run --restart=always nginx</code>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#full-docker-run-command-options", "title": "Full <code>docker run</code> command options", "text": "<pre><code>docker run -d \\\n  --name web \\\n  -p 8080:80 \\\n  -v /my/html:/usr/share/nginx/html \\\n  --network my_custom_net \\\n  nginx\n</code></pre> <p>This runs an <code>nginx</code> container:</p> <ul> <li>in detached mode</li> <li>named <code>web</code></li> <li>with port 8080 mapped to 80</li> <li>serving files from <code>/my/html</code></li> <li>on a custom network <code>my_custom_net</code></li> </ul>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#3-run-prebuilt-images-without-custom-source-code", "title": "3. Run prebuilt images without custom source code", "text": "Run prebuilt images Image Description Example nginx High-performance HTTP server &amp; reverse proxy docker run -d --name web -p 8080:80 nginx redis In-memory data structure docker run -d --name redis -p 6379:6379 redis postgres Open-source relational database docker run -d --name pg -e POSTGRES_PASSWORD=secret -p 5432:5432 postgres mysql Popular relational database system docker run -d --name mysql -e MYSQL_ROOT_PASSWORD=secret -p 3306:3306 mysql mongo NoSQL document database docker run -d --name mongo -p 27017:27017 mongo traefik Modern reverse proxy/load balancer docker run -d --name traefik -p 80:80 traefik (needs config) consul Service discovery and configuration docker run -d --name consul -p 8500:8500 consul etcd Distributed reliable key-value store docker run -d --name etcd quay.io/coreos/etcd vault Secrets and encryption management docker run -d --name vault -p 8200:8200 vault haproxy High performance TCP/HTTP load balancer docker run -d --name haproxy -p 80:80 haproxy (needs config) minio/minio S3-compatible object storage docker run -d --name minio -p 9000:9000 -e MINIO_ACCESS_KEY=minio -e MINIO_SECRET_KEY=minio123 minio/minio server /data rabbitmq Robust message broker supporting AMQP docker run -d --name rabbitmq -p 5672:5672 -p 15672:15672 rabbitmq:management grafana/grafana Analytics and monitoring dashboard docker run -d --name grafana -p 3000:3000 grafana/grafana prom/prometheus Monitoring &amp; alerting toolkit docker run -d --name prometheus -p 9090:9090 prom/prometheus", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#4-popular-basic-images-for-custom-docker-buils", "title": "4. Popular basic images for custom docker buils", "text": "Basic images Image Description Example python Python runtime (with pip) <code>FROM python:3.11</code> node Node.js runtime (with npm/yarn) <code>FROM node:20</code> golang Go compiler &amp; runtime Run go apps openjdk / eclipse-temurin Java runtime &amp; JDK <code>FROM eclipse-temurin:21</code> gcc GNU C/C++ compiler <code>FROM gcc:13</code> rust Rust compiler &amp; cargo <code>FROM rust:1.74</code> php PHP runtime <code>FROM php:8.3-apache</code> ruby Ruby &amp; gem environment <code>FROM ruby:3.3</code> alpine Lightweight Linux distro <code>FROM alpine</code> debian Full Linux OS base <code>FROM debian:bookworm</code> ubuntu Popular Linux distro base <code>FROM ubuntu:24.04</code> busybox Tiny Unix utilities <code>FROM busybox</code> dotnet .NET SDK &amp; runtime <code>FROM mcr.microsoft.com/dotnet/sdk:8.0</code> tensorflow/tensorflow Python + TensorFlow <code>FROM tensorflow/tensorflow:latest</code> pytorch/pytorch + TensorFlow Python + PyTorch <code>FROM pytorch/pytorch:latest</code>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#how-to-find-base-os-of-a-base-container", "title": "How to find Base OS of a base container", "text": "<p>Option 1: <pre><code>docker image inspect python:3.11-slim\n</code></pre></p> <p>Option 2: Run a shell in the container <pre><code>docker run -it --rm python:3.11-slim bash\ncat /etc/os-release\n</code></pre> This will show, <pre><code>PRETTY_NAME=\"Debian GNU/Linux 11 (bullseye)\"\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-commands.html#5-dockerfile-template", "title": "5. Dockerfile template", "text": "<pre><code>FROM python:3.11-slim\n\nWORKDIR /app\nCOPY . .\nRUN pip install -r requirements.txt\nCMD [\"python\", \"app.py\"]\n</code></pre> <p>Here, the base image (python:3.11-slim) includes:</p> <ul> <li>OS base (Debian/Alpine)</li> <li>Python interpreter</li> <li>pip</li> </ul> <p>Note: In <code>FROM python:3.11-slim</code>, you are using an image named python:3.11-slim, but it inherits from an underlying OS base \u2014 typically Debian.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html", "title": "A network example", "text": "<p>As explained earlier, Docker is a container that bundles application code along with the tools required to run it. In today\u2019s era of distributed computing, it's common for applications to communicate over networks using protocols like TCP or UDP.</p> <p>In addition to containerization, Docker also provides built-in tools to create virtual networks, enabling containers to communicate with each other seamlessly.</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#1-what-is-a-docker-network", "title": "1. What is a docker network", "text": "<p>A Docker network is a virtual communication layer that enables containers to interact with each other, whether they are running on the same machine or distributed across multiple hosts.</p> <ul> <li>It creates an isolated, software-defined environment for container networking.</li> <li>The example below shows two Docker containers communicating through such a virtual network.</li> <li>Both the containers and the virtual network are created and managed using Docker's built-in tools.</li> </ul> <p></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#2-protocols-supported", "title": "2. Protocols supported", "text": "<p>All Docker networks support: <pre><code>TCP\nUDP\nICMP (ping)\nAnd any other IP-based protocol your app uses.\n</code></pre></p> <p>It\u2019s you application inside the container (e.g. a Python script or C program) that chooses whether to use TCP or UDP </p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#3-an-example-application", "title": "3. An example application", "text": "<p>In this section, we demonstrate the concept of a Docker network by creating two Docker containers and one virtual network.</p> <ul> <li> <p>One container acts as a TCP server, waiting for incoming connections.</p> </li> <li> <p>The second container serves as a TCP client that connects to the server. Once connected, the server sends the message \"hello client 1, 2, 3\" every second.</p> </li> <li> <p>The virtual network is a Docker-managed component that establishes the TCP link between the server and the client, enabling seamless communication.</p> </li> </ul>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#how-many-containers-and-networks", "title": "How many containers and networks", "text": "<p>In this example, we will set up two containers\u2014one for the client and one for the server\u2014and connect them using a single network, as illustrated below</p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#3-directory-structure", "title": "3. Directory structure", "text": "<p>Create the following directory structure. Refer to the previous tutorial Hello Docker if you need a refresher.</p> <pre><code># we do not need any extra modules other than the standard ones\n# so we are removing requirments.txt file completely\ntcp-docker-app/\n\u251c\u2500\u2500 server/\n\u2502   \u251c\u2500\u2500 server.py\n\u2502   \u2514\u2500\u2500 Dockerfile\n\u2514\u2500\u2500 client/\n    \u251c\u2500\u2500 client.py\n    \u2514\u2500\u2500 Dockerfile\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#4-file-contents", "title": "4. File contents", "text": "", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#server-python", "title": "Server (Python)", "text": "<p><code>server/server.py</code> <pre><code>import socket\nimport time\n\nHOST = '0.0.0.0'   # Listen on all interfaces\nPORT = 5000        # Port to listen on\n\ndef start_server():\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server_socket:\n        server_socket.bind((HOST, PORT))\n        server_socket.listen(1)\n        print(f\"[SERVER] Listening on {HOST}:{PORT}...\")\n\n        conn, addr = server_socket.accept()\n        with conn:\n            print(f\"[SERVER] Connected by {addr}\")\n            counter = 1\n            while True:\n                message = f\"hello from server - msg {counter}\\n\"\n                conn.sendall(message.encode())\n                print(f\"[SERVER] Sent: {message.strip()}\")\n                counter += 1\n                time.sleep(1)\n\nif __name__ == \"__main__\":\n    start_server()\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#server-dockerfile", "title": "Server (Dockerfile)", "text": "<p><code>server/Dockerfile</code></p> <pre><code>FROM python:3.10-slim\nWORKDIR /app\nCOPY server.py .\nCMD [\"python\", \"server.py\"]\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#client-python", "title": "Client (Python)", "text": "<p><code>client/client.py</code> <pre><code>import socket\n\nSERVER_HOST = 'server-container'  # Replace with actual hostname or IP if needed\nSERVER_PORT = 5000\n\ndef start_client():\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n        print(f\"[CLIENT] Connecting to {SERVER_HOST}:{SERVER_PORT}...\")\n        s.connect((SERVER_HOST, SERVER_PORT))\n        print(\"[CLIENT] Connected. Waiting for messages...\\n\")\n        while True:\n            data = s.recv(1024)\n            if not data:\n                print(\"[CLIENT] Connection closed by server.\")\n                break\n            print(f\"[CLIENT] Received: {data.decode().strip()}\")\n\nif __name__ == \"__main__\":\n    start_client()\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#client-docker-file", "title": "Client (Docker file)", "text": "<p><code>client/Dockerfile</code></p> <pre><code># Use a lightweight Python base image\nFROM python:3.11-slim\n\n# Set the working directory inside the container\nWORKDIR /app\n\n# Copy the client script into the container\nCOPY client.py .\n\n# Set the default command to run the client\nCMD [\"python\", \"client.py\"]\n</code></pre>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#5-build-client-and-server-images", "title": "5. Build client and server images", "text": "", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#build-server-image", "title": "Build server image", "text": "<ol> <li>Open a terminal and navigate to the server folder.</li> <li>Build the Docker image: <pre><code>docker build -t my-tcp-server .\n</code></pre></li> </ol>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#build-client-images", "title": "Build client images", "text": "<ol> <li>Navigate to the client folder</li> <li>Build the client image: <pre><code>docker build -t my-tcp-client .\n</code></pre></li> </ol>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#check-the-docker-images", "title": "Check the docker images", "text": "<pre><code>sudo docker images\n</code></pre> <p>You should see something like this <pre><code>REPOSITORY       TAG       IMAGE ID       CREATED          SIZE\nmy-tcp-server    latest    abcdef123456   10 minutes ago   45MB\nmy-tcp-client    latest    123456abcdef   9 minutes ago    44MB\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#6-create-a-docker-network", "title": "6. Create a docker network", "text": "<p>Create a network named network-A to manage communication between the server and client Docker containers:</p> <pre><code>docker network create network-A\n</code></pre> <p>To verify that docker network is created: <pre><code>docker network ls\n</code></pre> Output shold look like <pre><code>NETWORK ID     NAME         DRIVER    SCOPE\nabcd1234efgh   network-A    bridge    local\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/docker-network-example.html#7-run-and-test-clientserver-dockers", "title": "7. Run and test client/server dockers", "text": "<p>In terminal 1 (run the server): <pre><code>docker run --rm -it --name server-container --network network-A my-tcp-server\n</code></pre></p> <p>In terminal 2 (run the client): <pre><code>docker run --rm -it --name client-container --network network-A my-tcp-client\n</code></pre></p>", "tags": ["Linux", "docker"]}, {"location": "tutorials/docker/tcp-example.html", "title": "A More Complex Example (TCP Server/Client)", "text": "", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#1the-objective", "title": "1.The Objective", "text": "<p>In this example, we are creating TWO docker apps.     - Docker 1: To run a TCP Server     - Docker 2: To run a TCP Clinet that connects to the above server - The server starts and waits for a connection request from client(s)</p> <p></p> <ul> <li> <p>When a TCP client connects to the server and passes its ID name to the server (e.g. TClient-1, TClient-2), which is passed through a command line. </p> </li> <li> <p>The server in turn, sends a greeting message to each client Hello from server to TCLinet1---Msg #</p> </li> <li> <p>Additionally, we can run multiple instances of client docker, and server handles each of them with their own greeting message.</p> </li> </ul>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#2-directory-structure", "title": "2. Directory structure", "text": "<p>Create the following directory structure. Refer to the previous tutorial Hello Docker if you need a refresher.</p> <pre><code># we do not need any extra modules other than the standard ones\n# so we are removing requirments.txt file completely\ntcp-docker-app/\n\u251c\u2500\u2500 server/\n\u2502   \u251c\u2500\u2500 server.py\n\u2502   \u2514\u2500\u2500 Dockerfile\n\u2514\u2500\u2500 client/\n    \u251c\u2500\u2500 client.py\n    \u2514\u2500\u2500 Dockerfile\n</code></pre>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#3-file-contents", "title": "3. File contents", "text": "", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#server-python", "title": "Server (Python)", "text": "<p><code>server/server.py</code> <pre><code>import socket\nimport time\n\nHOST = '0.0.0.0'\nPORT = 5000\n\ndef start_server():\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n        s.bind((HOST, PORT))\n        s.listen(1)\n        print(f\"[SERVER] Listening on {HOST}:{PORT}\")\n        conn, addr = s.accept()\n        with conn:\n            print(f\"[SERVER] Connected by {addr}\")\n            counter = 1\n            while True:\n                message = f\"hello-client1-msg {counter}\\n\"\n                conn.sendall(message.encode())\n                print(f\"[SERVER] Sent: {message.strip()}\")\n                counter += 1\n                time.sleep(1)\n\nif __name__ == \"__main__\":\n    start_server()\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#server-dockerfile", "title": "Server (Dockerfile)", "text": "<p><code>server/Dockerfile</code> <pre><code>FROM python:3.10-slim\nWORKDIR /app\nCOPY server.py .\nCMD [\"python\", \"server.py\"]\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#client-python", "title": "Client (Python)", "text": "<p><code>client/client.py</code> <pre><code>import socket\n\nSERVER_HOST = 'server-container'  # container name of the server\nSERVER_PORT = 5000\n\ndef start_client():\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n        print(f\"[CLIENT] Connecting to {SERVER_HOST}:{SERVER_PORT}\")\n        s.connect((SERVER_HOST, SERVER_PORT))\n        while True:\n            data = s.recv(1024)\n            if not data:\n                break\n            print(f\"[CLIENT] Received: {data.decode().strip()}\")\n\nif __name__ == \"__main__\":\n    start_client()\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#client-docker-file", "title": "Client (Docker file)", "text": "<p><code>client/Dockerfile</code> <pre><code>FROM python:3.10-slim\nWORKDIR /app\nCOPY client.py .\nCMD [\"python\", \"client.py\"]\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#4-build-docker-images", "title": "4. Build docker images", "text": "<p><code>server</code> <pre><code>cd tcp-docker-app/server\nsudo docker build -t tcp-server .\n</code></pre></p> <p><code>client</code> <pre><code>cd tcp-docker-app/client\nsudo docker build -t tcp-client .\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#verify-the-build", "title": "Verify the build", "text": "<p><pre><code>sudo docker images\n</code></pre> If everything was built correctly, you should see an output: <pre><code>REPOSITORY        TAG       IMAGE ID       CREATED              SIZE\ntcp-client        latest    3a7e23eb624a   59 seconds ago       127MB\ntcp-server        latest    8aa392e6b1e3   About a minute ago   127MB\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#5-run-server-client-network", "title": "5. Run (server, client, network)", "text": "", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#create-a-docker-network", "title": "Create a docker network", "text": "<pre><code>sudo docker network create tcp-net\n</code></pre>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#run-the-server-container", "title": "Run the server container", "text": "<p><code>In Terinal-1</code> <pre><code>sudo docker run  --rm -it --name server-container --network tcp-net tcp-server\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#run-the-client-container-1", "title": "Run the Client container (1)", "text": "<p><code>In Terminal-2</code> <pre><code>sudo docker run --rm -it --name client-container1 --network tcp-net tcp-client python client.py Client-1\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/docker/tcp-example.html#run-the-client-container-2", "title": "Run the Client container (2)", "text": "<p><code>In Terminal-2</code> <pre><code>sudo docker run --rm -it --name client-container2 --network tcp-net tcp-client python client.py Client-1\n</code></pre></p>", "tags": ["docker", "tcp server", "tcp client"]}, {"location": "tutorials/linux/linux-cli.html", "title": "Linux CLI Reference", "text": "<p>This page provides quick-access cheat sheets for Linux CLI commands.</p>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#files-and-directories", "title": "Files and Directories", "text": "Files and Directories (click to view) Navigation and ListingCreating &amp; RemovingCopying &amp; MovingViewingFile Info command description <code>ls</code> List files and folders in the current directory <code>ls -l</code> List with detailed info (permissions, size, date) <code>ls -a</code> List all files, including hidden ones (. files) <code>pwd</code> Show current directory path <code>cd [directory]</code> Change directory <code>cd ..</code> Go up one directory level <code>cd</code> Go to home directory of the logged-in user command description <code>mkdir [foldername</code> Create a new folder <code>rmdir [foldername]</code> Remove an empty folder <code>rm -r [foldername]</code> Remove a folder and its contents recursively <code>touch [filename]</code> Create an empty file or update timestamp <code>rm [filename]</code> Remove a file command description <code>cp [source] [destination]</code> Copy file <code>cp -r [source_folder] [destination_folder]</code> Copy folder recursively <code>mv [source] [destination]</code> Move or rename files/folders command description <code>cat [filename]</code> Display file content <code>less [filename]</code> View file content page by page <code>head [filename]</code> Show first 10 lines of a file <code>tail [filename]</code> Show last 10 lines of a file command description <code>file [filename]</code> Show file type <code>stat [filename]</code> Detailed info about a file or folder", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#file-searching", "title": "File Searching", "text": "File Searching (click to view) Navigation and ListingBasic exampleMore examples of find command description <code>find [path] -name \"[pattern]\"</code> Search for files by name <code>locate [filename]</code> Quickly find a file by name (database-based)) <code>grep \"[text]\" [filename]</code> Search for text inside a file command description <code>find . -name \"*.txt\"</code> Find all .txt files in the current directory and subdirectories <code>locate [filename]</code> Quickly find a file by name (database-based)) <code>find /home/user -name \"notes.md\"</code> Find a file named notes.md anywhere in /home/user <code>find /tmp -name \"*.tmp\" -exec rm {} \\;</code> Find and delete all .tmp files in /tmp command description <code>find /etc -type f -name \"*.conf\" -exec realpath {} \\;</code> List full path of all .conf files <code>find /var/log -type f -name \"*.log\" -exec du -h {} \\;</code> Print file size of .log files <code>find /var/log -type f -name \"*.log\" -size +1M -exec rm {} \\;</code> Delete log files of size above 1MB (using rm shell command) <code>find /var/log -type f -name \"*.log\" -size +1M -delete</code> Delete log files of size above 1MB (using -delete flag) <code>find /tmp -type f -name \"*.tmp\" -exec rm {} \\;</code> Delete all .tmp files <code>find . -type f -empty -exec rm {} \\;</code> Delete empty files <code>find /backup -type f -mtime +30 -exec rm {} \\;</code> Delete files older than 30 days <code>find ~/Downloads -type f -mtime +30 -exec rm {} \\;</code> Delete files older than 30 days <p>Note: -exec is not the same as the shell\u2019s built-in exec command \u2014 they're totally different things, even though they share the word \"exec.\"</p> <ul> <li>exec some_command  (this is part of shell itself)</li> <li>The -exec Option in the find Command is not same as exec...It is just an option of the 'find command itself\"</li> <li>to delete log files \"-delete\" option is better than \"rm\", because it is a built-in parameter of \"find\" command. It's generally faster and uses less system resources because it doesn\u2019t need to spawn a new rm process for each file. (both ways are mentioned in above examples)</li> </ul>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#execute-a-command-exec-vs-exec", "title": "execute a command (exec vs -exec)", "text": "File/Content Searching (click to view) exec commandDescriptionSome Examples <pre><code>exec command [arguments]\n</code></pre> <ul> <li>The exec command is a shell builtin that replaces the current shell process with a specified command, running that command directly without creating a new process.</li> <li>After exec runs, the original shell session is replaced and does not return to the previous shell.</li> </ul> <pre><code>#This replaces the current shell with the ls -l command.\n#Once ls finishes listing files, the session ends (you won\u2019t get a prompt back).\nexec ls -l\n\n\n#Delete all .bak files in the current directory and subdirectories\nfind . -type f -name \"*.bak\" -exec rm {} \\;\n</code></pre>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#exec-vs-exec", "title": "exec vs -exec", "text": "<ul> <li> <p>-exec is not the same as the shell\u2019s built-in exec command \u2014 they're totally different things, even though they share the word \"exec.\"</p> </li> <li> <p>exec some_command (this is part of shell itself) The -exec Option in the find Command is not same as exec...It is just an option of the 'find command itself\"</p> </li> </ul>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#when-to-use-exec", "title": "When to use \"exec\"", "text": "When to use exec (click to find out about various scenarios/use-cases) <ul> <li> <p>It is used to Replace the Shell with Another Program: Useful in scripts or login environments where you want to run a program instead of a shell \u2014 and don\u2019t need to return.</p> </li> <li> <p>To Save Memory in Scripts: In long-running scripts, especially daemons, using exec prevents spawning a new process. It replaces the shell, saving memory and process overhead.</p> </li> <li> <p>To Redirect Input/Output for the Entire Shell or Script: exec can be used to change stdin, stdout, or stderr at the shell level \u2014 affecting all commands that follow.</p> </li> <li> <p>To Replace the Shell in System Startup Scripts: In init or systemd environments, exec is used so that the shell process doesn\u2019t hang around. This is cleaner and avoids zombie processes.</p> </li> <li>To Chain Commands with Replacement: You can use it at the end of a script to \"handoff\" control to another process, especially for chaining tools or launching shells.</li> </ul>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#when-not-to-use-exec", "title": "When NOT to use \"exec\"", "text": "When NOT to use exec (click to find out) <ul> <li> <p>Once executed, the shell is gone. If you accidentally use exec instead of running a command normally, your terminal may close (especially with GUI apps).</p> </li> <li> <p>For most everyday tasks (like ls, rm, etc.), you should just run the command normally, not with exec.</p> </li> </ul>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#finding-text-in-files", "title": "Finding text in file(s)", "text": "", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#grep-command", "title": "grep command", "text": "grep (click to view) Basic syntaxSome examples <p><pre><code>grep [options] \"pattern\" [file...]\n</code></pre> <pre><code># for example\ngrep \"search_text\" filename\n</code></pre></p> <pre><code>#Find lines containing \"TODO\" in a file\ngrep \"TODO\" myscript.py\n\n#Recursively search all files in a directory for \"main()\"\ngrep -r \"main()\" /home/user1/code/\n\n#Search \"error\" ignoring case sensitivity\ngrep -i \"error\" server.log\n\n#Show line numbers where \"function\" appears\ngrep -n \"function\" script.sh\n\n#Match the whole word \"init\" (not \"initialize\", etc.)\ngrep -w \"init\" config.yaml\n\n#Search all non-binary files for \"password\"\n# The -I option tells grep to ignore binary files. (i.e. non-text files)\ngrep -I \"password\" *\n\n#Save results to a file (instead of displaying on the screen)\ngrep \"error\" logfile.txt &gt; results.txt\n\n#Suppress permission denied errors\ngrep -r \"password\" /etc 2&gt;/dev/null\n</code></pre>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#awk-tool", "title": "awk tool", "text": "<ul> <li>awk is an alternative to grep</li> <li>Its an advanced tool and will be described in a separate section</li> </ul>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#user-and-permission-managment", "title": "User and Permission Managment", "text": "<p>WIP</p>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#file-compression-and-archiving", "title": "File Compression and Archiving", "text": "<p>WIP</p>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#system-monitoring-and-process-management", "title": "System Monitoring and Process Management", "text": "<p>WIP</p>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#package-management", "title": "Package Management", "text": "<p>WIP</p>", "tags": ["Linux"]}, {"location": "tutorials/linux/linux-cli.html#networking", "title": "Networking", "text": "<p>WIP</p>", "tags": ["Linux"]}, {"location": "blog/archive/2025.html", "title": "2025", "text": ""}, {"location": "blog/category/programming.html", "title": "Programming", "text": ""}, {"location": "blog/category/5g-communication.html", "title": "5G-Communication", "text": ""}]}